INSERT INTO `page_about` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/about/', 'Завод металлопластиковых конструкций «Спектр»', '{"main_html":"<main id=\"content\">\n    <section class=\"about-hero wrap\" aria-labelledby=\"about-title\">\n    <nav class=\"breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../\">Главная</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">О нас</span></nav>\n      <div class=\"about-intro section-copy\">\n\n        <h1 id=\"about-title\">Завод металлопластиковых<br><em class=\"heading-accent\">конструкций «Спектр»</em></h1>\n        <p>Изготавливаем и устанавливаем пластиковые окна, двери и алюминиевые конструкции по вашим размерам — для квартиры, дома или бизнеса.</p>\n        <p>В наших офисах в Ростовской области и Краснодарском крае можно посмотреть образцы, сравнить комплектации и обсудить заказ.</p>\n        <a class=\"secondary-link\" href=\"#approach\">Больше о компании <span aria-hidden=\"true\">↓</span></a>\n      </div>\n    </section>\n    <div class=\"about-facts wrap\" aria-label=\"Спектр в фактах\">\n      <div><strong>2004<span>год</span></strong><p>работаем с окнами и остеклением</p></div>\n      <div><strong>6<span>офисов</span></strong><p>в Ростовской области и Краснодарском крае</p></div>\n      <div><strong>Ваш<span>размер</span></strong><p>изготовление под конкретный проём</p></div>\n    </div>\n    <section class=\"about-section wrap about-tasks\" id=\"approach\" aria-labelledby=\"tasks-title\">\n      <div class=\"about-section-heading section-copy\"><h2 id=\"tasks-title\">Какие задачи<br><em class=\"heading-accent\">мы помогаем решить?</em></h2></div>\n      <ol class=\"about-task-list\" aria-label=\"Задачи, с которыми мы помогаем\">\n        <li><span class=\"about-task-number\" aria-hidden=\"true\">1</span><h3>Сохранить тепло</h3><p>Подбираем профиль и стеклопакет с учётом помещения. Предлагаем комплектации с теплосберегающим стеклом.</p></li>\n        <li><span class=\"about-task-number\" aria-hidden=\"true\">2</span><h3>Снизить уличный шум</h3><p>Учитываем, куда выходят окна. Подбираем остекление, уплотнение и способ открывания.</p></li>\n        <li><span class=\"about-task-number\" aria-hidden=\"true\">3</span><h3>Защититься от солнца</h3><p>Предлагаем мультифункциональное стекло и рулонные шторы для регулировки света.</p></li>\n        <li><span class=\"about-task-number\" aria-hidden=\"true\">4</span><h3>Остеклить балкон</h3><p>Помогаем выбрать тёплое ПВХ-остекление или холодную алюминиевую конструкцию под назначение балкона.</p></li>\n        <li><span class=\"about-task-number\" aria-hidden=\"true\">5</span><h3>Удобно открывать окно</h3><p>Подбираем створки, ручки и фурнитуру. Для широких проёмов рассматриваем раздвижные системы и порталы.</p></li>\n        <li><span class=\"about-task-number\" aria-hidden=\"true\">6</span><h3>Оформить вход и интерьер</h3><p>Изготавливаем двери, витрины и алюминиевые перегородки для жилых и коммерческих помещений.</p></li>\n      </ol>\n    </section>\n    <section class=\"about-approach wrap about-section\" aria-labelledby=\"approach-title\">\n      <div class=\"about-section-heading section-copy\"><h2 id=\"approach-title\">Почему выбирают<br><em class=\"heading-accent\">«Спектр»</em></h2></div>\n      <div class=\"approach-grid\">\n        <p class=\"approach-lead\">Работаем с квартирами, частными домами и коммерческими помещениями. Помогаем разобраться в выборе и согласовать детали до изготовления.</p>\n        <ol class=\"principles\" aria-label=\"О компании и работе с заказом\">\n          <li><span aria-hidden=\"true\">1</span><div><h3>В деле с 2004 года</h3><p>Производим и устанавливаем окна, двери и конструкции для остекления.</p></div></li>\n          <li><span aria-hidden=\"true\">2</span><div><h3>Шесть офисов в двух регионах</h3><p>Ростов-на-Дону, Азов, Батайск, Кулешовка и Ейск. Работаем в Ростовской области и Краснодарском крае.</p></div></li>\n          <li><span aria-hidden=\"true\">3</span><div><h3>Изготовление по вашим размерам</h3><p>Учитываем проём, назначение помещения и пожелания к конструкции.</p></div></li>\n          <li><span aria-hidden=\"true\">4</span><div><h3>Образцы можно посмотреть вживую</h3><p>В офисах поможем сравнить профиль, стеклопакеты и фурнитуру, ответим на вопросы.</p></div></li>\n          <li><span aria-hidden=\"true\">5</span><div><h3>Сначала согласуем стоимость</h3><p>Калькулятор даёт ориентир. Точную сумму уточняем после замера и согласования комплектации, доставки и монтажа.</p></div></li>\n          <li><span aria-hidden=\"true\">6</span><div><h3>От замера до установки</h3><p>Помогаем с выбором, проводим замер, изготавливаем и устанавливаем конструкции.</p></div></li>\n        </ol>\n      </div>\n    </section>\n    <section class=\"about-solutions\" aria-labelledby=\"solutions-title\">\n      <div class=\"wrap about-section\">\n        <div class=\"about-section-heading section-copy\"><h2 id=\"solutions-title\">Для дома<br><em class=\"heading-accent\">и бизнеса</em></h2></div>\n        <div class=\"solution-grid\">\n          <a class=\"solution-card\" href=\"../catalog/?category=windows\"><span class=\"solution-index\">Окна <span aria-hidden=\"true\">↗</span></span><h3>Пластиковые окна</h3><p>Профильные системы REHAU и PRO WINS, готовые комплектации «Спектр» и окна нестандартной формы.</p><span class=\"solution-link\">Посмотреть варианты →</span></a>\n          <a class=\"solution-card\" href=\"../catalog/?category=aluminium\"><span class=\"solution-index\">Алюминиевые конструкции <span aria-hidden=\"true\">↗</span></span><h3>Алюминиевые конструкции</h3><p>Раздвижные окна, порталы, панорамное остекление, фасады и перегородки.</p><span class=\"solution-link\">Посмотреть варианты →</span></a>\n          <a class=\"solution-card\" href=\"../catalog/?category=doors\"><span class=\"solution-index\">Двери <span aria-hidden=\"true\">↗</span></span><h3>Двери из ПВХ</h3><p>Входные, межкомнатные и балконные двери с подбором заполнения и открывания.</p><span class=\"solution-link\">Посмотреть варианты →</span></a>\n        </div>\n        <p class=\"about-range-note\">Также в каталоге: остекление балконов, ворота и рольставни, натяжные потолки и рулонные шторы. <a href=\"../catalog/\">Вся продукция ↗</a></p>\n      </div>\n    </section>\n    <section class=\"about-section wrap about-work\" aria-labelledby=\"work-title\">\n      <div class=\"about-section-heading section-copy\"><h2 id=\"work-title\">Наши <em class=\"heading-accent\">работы</em></h2><p>Фотографии из нашей галереи: посмотрите, как конструкции выглядят на объектах.</p></div>\n      <div class=\"about-work-grid\">\n        <a href=\"../solutions/\" aria-label=\"Посмотреть галерею выполненных работ\"><img src=\"../assets/solutions/thumbs/photo_2026-10-08 10.29.26 AM.webp?v=20261024-optimized\" alt=\"Остекление на объекте из галереи Спектра\" width=\"640\" height=\"854\" loading=\"lazy\" decoding=\"async\"></a>\n        <a href=\"../solutions/\" aria-label=\"Посмотреть другие выполненные работы\"><img src=\"../assets/solutions/thumbs/photo_2026-10-08 10.29.28 AM.webp?v=20261024-optimized\" alt=\"Оконная конструкция из галереи Спектра\" width=\"640\" height=\"854\" loading=\"lazy\" decoding=\"async\"></a>\n        <a href=\"../solutions/\" aria-label=\"Открыть примеры работ Спектра\"><img src=\"../assets/solutions/thumbs/photo_2026-10-08 10.29.29 AM.webp?v=20261024-optimized\" alt=\"Пример выполненного остекления из галереи Спектра\" width=\"640\" height=\"854\" loading=\"lazy\" decoding=\"async\"></a>\n      </div>\n      <a class=\"secondary-link\" href=\"../solutions/\">Все примеры работ <span aria-hidden=\"true\">↗</span></a>\n    </section>\n    <section class=\"about-invitation wrap\" aria-labelledby=\"invitation-title\"><div><h2 id=\"invitation-title\">Обсудим<br><em class=\"heading-accent\">ваш заказ</em></h2><p>Выберите ближайший офис или позвоните — поможем с выбором и расчётом.</p></div><div class=\"invitation-actions\"><a class=\"primary-link page-end-action page-end-action-text\" href=\"../contacts/\"><span class=\"page-end-action-label\">Адреса офисов</span><span class=\"page-end-action-arrow\" aria-hidden=\"true\">↗</span></a><a class=\"invitation-call page-end-action\" href=\"tel:+79895175699\" aria-label=\"Позвонить в Спектр: 8 (989) 517-56-99\"><svg class=\"page-end-action-icon\" viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"m7 3 3 5-2.5 2.5a15 15 0 0 0 6 6L16 14l5 3c0 3-2 4-4 4C10 20 4 14 3 7c0-2 1-4 4-4Z\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg><span class=\"page-end-action-copy\"><span>Позвонить в «Спектр»</span><strong>8 (989) 517-56-99</strong></span><span class=\"page-end-action-arrow\" aria-hidden=\"true\">↗</span></a></div></section>\n  </main>"}', 'Завод металлопластиковых конструкций «Спектр» — о компании', 'Производим пластиковые окна, двери и алюминиевые конструкции по размерам заказчика. О компании «Спектр», выборе комплектации и работе с клиентами.', 'https://spektr-okna.ru/about/')
ON DUPLICATE KEY UPDATE id = id;

-- /articles/bezopasnye-okna-dlya-detey/
INSERT INTO `page_articles` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/articles/bezopasnye-okna-dlya-detey/', 'Безопасные окна для детей: что предусмотреть при заказе', '{"main_html":"<main id=\"content\" class=\"article-detail wrap\">\n    <nav class=\"article-breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Статьи</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Безопасность</span></nav>\n    <article>\n      <header class=\"article-heading\"><h1>Безопасные окна для детей: <em class=\"heading-accent\">что предусмотреть при заказе</em></h1><div class=\"article-heading-meta\"><span><time datetime=\"2026-10-09\">09.10.2026</time></span><span>Чтение: около 2 мин</span></div></header>\n      <div class=\"article-content\">\n      <figure class=\"article-cover\"><img src=\"../../assets/solutions/photo_2026-10-08 10.29.37 AM.webp?v=20261024-optimized\" srcset=\"../../assets/solutions/thumbs/photo_2026-10-08%2010.29.37%E2%80%AFAM.webp?v=20261024-optimized 640w, ../../assets/solutions/photo_2026-10-08%2010.29.37%E2%80%AFAM.webp?v=20261024-optimized 1600w\" sizes=\"(max-width: 480px) calc(100vw - 32px), (max-width: 760px) calc(100vw - 40px), (max-width: 1100px) calc(100vw - 56px), (max-width: 1416px) calc(100vw - 96px), 1320px\" alt=\"Остекление из галереи «Спектра»\" width=\"1600\" height=\"3556\" fetchpriority=\"high\" decoding=\"async\"><figcaption>Фото из галереи «Спектра»</figcaption></figure>\n      <div class=\"article-body\"><section id=\"section-1\"><h2>Москитная сетка <em class=\"heading-accent\">не удерживает человека</em></h2><p>Москитная сетка защищает от насекомых, но не от падения — даже усиленный вариант нельзя считать опорой. Объясняйте это детям и ограничивайте опасное открывание. Не оставляйте ребёнка без присмотра рядом с открытым окном.</p></section>\n<section id=\"section-2\"><h2>Чем <em class=\"heading-accent\">отличаются устройства</em></h2><p>Ручка с ключом блокирует управление; замки и ограничители могут сохранять отдельные режимы проветривания. Возможности зависят от модели. Попросите показать, что устройство блокирует: обычный ограничитель для удобства не обязательно предназначен для детской безопасности.</p></section>\n<section id=\"section-3\"><h2>Проверьте <em class=\"heading-accent\">совместимость и монтаж</em></h2><p>Устройство должно подходить профилю и фурнитуре. Для существующего окна требуется проверка мест крепления. Монтаж выполняют по инструкции; взрослый проверяет работу и состояние креплений. Храните ключи вне доступа детей и уточните правила обслуживания.</p></section>\n<section id=\"section-4\"><h2>Организуйте <em class=\"heading-accent\">пространство у окна</em></h2><p>Уберите от окна мебель, по которой ребёнок может забраться на подоконник. Не используйте его для игр. Проверьте все доступные окна и балконную дверь. Замки не заменяют присмотр, а безопасное стекло не защищает от выпадения через открытую створку.</p></section>\n<section id=\"section-5\"><h2>Вопросы <em class=\"heading-accent\">перед заказом</em></h2><p>Уточните возможности устройства до заказа.</p><ul><li>Для какой задачи предназначено выбранное устройство?</li><li>Какие режимы открывания оно блокирует и какие сохраняет?</li><li>Совместимо ли оно с нашей конструкцией и кто его устанавливает?</li><li>Как проверять исправность и где хранить ключи?</li></ul></section><aside class=\"article-takeaway\"><span class=\"eyebrow\">Главная мысль</span><p>Предусмотрите подходящее ограничение открывания, безопасную обстановку у окна и постоянный присмотр взрослых.</p></aside>\n      </div>\n      </div>\n    </article>\n  </main>","article":{"slug":"bezopasnye-okna-dlya-detey","legacy_slug":"kak-pravilno-zameryat-okna-poshagovoe-rukovodstvo-dlya-podgotovki-k-ostekleniyu","title":"Безопасные окна для детей: что предусмотреть при заказе","category":"Безопасность","description":"Чем отличаются замки и ограничители, почему сетка не защищает от падения и какие привычки важны дома.","intro":"Если дома есть ребёнок, безопасность нужно обсуждать одновременно с профилем и стеклопакетом. Обычная ручка доступна маленьким детям, а москитная сетка создаёт опасное ощущение опоры. Разберём, какие решения стоит предусмотреть заранее.","sections":[{"heading":"Москитная сетка не удерживает человека","paragraphs":["Москитная сетка защищает от насекомых, но не от падения — даже усиленный вариант нельзя считать опорой. Объясняйте это детям и ограничивайте опасное открывание. Не оставляйте ребёнка без присмотра рядом с открытым окном."],"heading_accent":"не удерживает человека"},{"heading":"Чем отличаются устройства","paragraphs":["Ручка с ключом блокирует управление; замки и ограничители могут сохранять отдельные режимы проветривания. Возможности зависят от модели. Попросите показать, что устройство блокирует: обычный ограничитель для удобства не обязательно предназначен для детской безопасности."],"heading_accent":"отличаются устройства"},{"heading":"Проверьте совместимость и монтаж","paragraphs":["Устройство должно подходить профилю и фурнитуре. Для существующего окна требуется проверка мест крепления. Монтаж выполняют по инструкции; взрослый проверяет работу и состояние креплений. Храните ключи вне доступа детей и уточните правила обслуживания."],"heading_accent":"совместимость и монтаж"},{"heading":"Организуйте пространство у окна","paragraphs":["Уберите от окна мебель, по которой ребёнок может забраться на подоконник. Не используйте его для игр. Проверьте все доступные окна и балконную дверь. Замки не заменяют присмотр, а безопасное стекло не защищает от выпадения через открытую створку."],"heading_accent":"пространство у окна"},{"heading":"Вопросы перед заказом","paragraphs":["Уточните возможности устройства до заказа."],"items":["Для какой задачи предназначено выбранное устройство?","Какие режимы открывания оно блокирует и какие сохраняет?","Совместимо ли оно с нашей конструкцией и кто его устанавливает?","Как проверять исправность и где хранить ключи?"],"heading_accent":"перед заказом"}],"takeaway":"Предусмотрите подходящее ограничение открывания, безопасную обстановку у окна и постоянный присмотр взрослых.","consultation":"Сообщите, что в доме есть дети, при обсуждении комплектации: уточним доступные устройства и их совместимость.","related":["kak-vybrat-plastikovye-okna-dlya-kvartiry","ukhod-za-plastikovymi-oknami"],"author":"Редакция «Спектра»","published_on":"2026-10-09","modified_on":"2026-10-09","content_kind":"original","image":{"path":"assets/solutions/thumbs/photo_2026-10-08 10.29.37 AM.webp","width":640,"height":1423,"alt":"Остекление из галереи «Спектра»","full_width":1600,"full_height":3556},"title_accent":"что предусмотреть при заказе"},"views":0}', 'Безопасные окна для детей: что предусмотреть при заказе — Спектр', 'Чем отличаются замки и ограничители, почему сетка не защищает от падения и какие привычки важны дома.', 'https://spektr-okna.ru/articles/bezopasnye-okna-dlya-detey/')
ON DUPLICATE KEY UPDATE id = id;

