INSERT INTO `page_articles` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/articles/', 'Об окнах — простыми словами', '{"main_html":"<main id=\"content\" class=\"articles-main wrap\">\n  <nav class=\"breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../\">Главная</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Статьи</span></nav>\n  <section class=\"articles-intro\" aria-labelledby=\"articles-title\">\n    <div class=\"section-copy\"><h1 id=\"articles-title\">Об окнах —<br><em class=\"heading-accent\">простыми словами</em></h1><p>Как выбрать окна, разобраться в стоимости и подготовиться к установке.</p></div>\n  </section>\n  <section class=\"articles-grid\" aria-label=\"Превью статей\"><article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./kak-vybrat-plastikovye-okna-dlya-kvartiry/\" aria-label=\"Как выбрать пластиковые окна для квартиры и не переплатить\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/apartment-installation.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"1422\" fetchpriority=\"high\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Как выбрать пластиковые окна для квартиры <em class=\"heading-accent\">и не переплатить</em></h2><p>С чего начать выбор, какие характеристики сравнивать и какие вопросы задать перед заказом.</p></div>\n    </a>\n  </article>\n<article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./skolko-stoyat-okna-pod-klyuch/\" aria-label=\"Сколько стоят окна под ключ: что должно входить в расчёт\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/brick-house-windows.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"853\" loading=\"lazy\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Сколько стоят окна под ключ: <em class=\"heading-accent\">что должно входить в расчёт</em></h2><p>Почему цена окна и сумма заказа отличаются, как сравнить сметы и где возможна разумная экономия.</p></div>\n    </a>\n  </article>\n<article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./kakoy-steklopaket-vybrat/\" aria-label=\"Какой стеклопакет выбрать: камеры, тепло и полезные покрытия\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/panoramic-gable.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"853\" loading=\"lazy\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Какой стеклопакет выбрать: <em class=\"heading-accent\">камеры, тепло и полезные покрытия</em></h2><p>Чем стеклопакет отличается от профиля и как подобрать стекло для тепла, тишины и солнцезащиты.</p></div>\n    </a>\n  </article>\n<article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./okna-dlya-zashchity-ot-shuma/\" aria-label=\"Какие окна выбрать, если мешает шум с улицы\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/apartment-installation.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"1422\" loading=\"lazy\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Какие окна выбрать, <em class=\"heading-accent\">если мешает шум с улицы</em></h2><p>Как подойти к выбору окна рядом с дорогой и почему важны стеклопакет, монтаж и проветривание.</p></div>\n    </a>\n  </article>\n<article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./okna-na-solnechnuyu-storonu/\" aria-label=\"Окна на солнечную сторону: как уменьшить жару в комнате\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/roller-shutter-open.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"400\" loading=\"lazy\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Окна на солнечную сторону: <em class=\"heading-accent\">как уменьшить жару в комнате</em></h2><p>Как совместить солнцезащиту, дневной свет и комфорт зимой без лишних обещаний.</p></div>\n    </a>\n  </article>\n<article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./pochemu-zapotevayut-plastikovye-okna/\" aria-label=\"Почему запотевают пластиковые окна и что проверить сначала\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/balcony-sill.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"853\" loading=\"lazy\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Почему запотевают пластиковые окна и <em class=\"heading-accent\">что проверить сначала</em></h2><p>Как различить конденсат в комнате и влагу внутри стеклопакета, проверить вентиляцию и понять, когда нужен мастер.</p></div>\n    </a>\n  </article>\n<article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./teploe-ili-kholodnoe-osteklenie-balkona/\" aria-label=\"Тёплое или холодное остекление балкона: что выбрать\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/balcony-sill.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"853\" loading=\"lazy\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Тёплое или холодное остекление балкона: <em class=\"heading-accent\">что выбрать</em></h2><p>Как связать тип остекления с назначением балкона и почему одних новых окон недостаточно для тёплой комнаты.</p></div>\n    </a>\n  </article>\n<article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./ustanovka-okon-podgotovka-i-priemka/\" aria-label=\"Установка окон: как подготовиться и что проверить при приёмке\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/frame-house-window.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"853\" loading=\"lazy\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Установка окон: <em class=\"heading-accent\">как подготовиться и что проверить при приёмке</em></h2><p>Понятный порядок от замера до проверки створок, швов и отделки после установки.</p></div>\n    </a>\n  </article>\n<article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./bezopasnye-okna-dlya-detey/\" aria-label=\"Безопасные окна для детей: что предусмотреть при заказе\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/photo_2026-10-08 10.29.37 AM.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"1423\" loading=\"lazy\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Безопасные окна для детей: <em class=\"heading-accent\">что предусмотреть при заказе</em></h2><p>Чем отличаются замки и ограничители, почему сетка не защищает от падения и какие привычки важны дома.</p></div>\n    </a>\n  </article>\n<article class=\"article-card\">\n    <a class=\"article-card-link\" href=\"./ukhod-za-plastikovymi-oknami/\" aria-label=\"Уход за пластиковыми окнами: мытьё, уплотнители и фурнитура\">\n      <div class=\"article-image\"><img src=\"../assets/solutions/thumbs/window-with-screen.webp?v=20261024-optimized\" alt=\"\" width=\"640\" height=\"853\" loading=\"lazy\" decoding=\"async\"></div>\n      <div class=\"article-copy\"><div class=\"article-meta\"><time datetime=\"2026-10-09\">09.10.2026</time></div><h2>Уход за пластиковыми окнами: <em class=\"heading-accent\">мытьё, уплотнители и фурнитура</em></h2><p>Как ухаживать за окном без царапин, что проверять регулярно и когда регулировку лучше поручить мастеру.</p></div>\n    </a>\n  </article></section>\n</main>","article_slugs":["kak-vybrat-plastikovye-okna-dlya-kvartiry","skolko-stoyat-okna-pod-klyuch","kakoy-steklopaket-vybrat","okna-dlya-zashchity-ot-shuma","okna-na-solnechnuyu-storonu","pochemu-zapotevayut-plastikovye-okna","teploe-ili-kholodnoe-osteklenie-balkona","ustanovka-okon-podgotovka-i-priemka","bezopasnye-okna-dlya-detey","ukhod-za-plastikovymi-oknami"]}', 'Статьи об окнах — Спектр', 'Выбор окон, защита от шума и жары, уход и монтаж: полезные разборы и советы для вашего дома.', 'https://spektr-okna.ru/articles/')
