INSERT INTO `page_articles` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/articles/okna-dlya-zashchity-ot-shuma/', 'Какие окна выбрать, если мешает шум с улицы', '{"main_html":"<main id=\"content\" class=\"article-detail wrap\">\n    <nav class=\"article-breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Статьи</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Тишина дома</span></nav>\n    <article>\n      <header class=\"article-heading\"><h1>Какие окна выбрать, <em class=\"heading-accent\">если мешает шум с улицы</em></h1><div class=\"article-heading-meta\"><span><time datetime=\"2026-10-09\">09.10.2026</time></span><span>Чтение: около 2 мин</span></div></header>\n      <div class=\"article-content\">\n      <figure class=\"article-cover\"><img src=\"../../assets/solutions/apartment-installation.webp?v=20261024-optimized\" srcset=\"../../assets/solutions/thumbs/apartment-installation.webp?v=20261024-optimized 640w, ../../assets/solutions/apartment-installation.webp?v=20261024-optimized 810w\" sizes=\"(max-width: 480px) calc(100vw - 32px), (max-width: 760px) calc(100vw - 40px), (max-width: 1100px) calc(100vw - 56px), (max-width: 1416px) calc(100vw - 96px), 1320px\" alt=\"Окно в проёме до отделки откосов\" width=\"810\" height=\"1800\" fetchpriority=\"high\" decoding=\"async\"><figcaption>Окно в квартире с видом на город: защиту от шума подбирают по условиям за окном, а не по внешнему виду.</figcaption></figure>\n      <div class=\"article-body\"><section id=\"section-1\"><h2>Определите, <em class=\"heading-accent\">откуда приходит звук</em></h2><p>Расскажите, какой звук мешает: поток машин, гул грузовиков или голоса. Проверьте разницу при закрытой створке. Шум может проникать через прижим, монтажные швы и вентиляцию. Иногда стоит сначала проверить существующее окно, а затем решать вопрос о замене.</p></section>\n<section id=\"section-2\"><h2>Почему обычного <em class=\"heading-accent\">толстого стекла недостаточно</em></h2><p>Звукоизоляция зависит от сочетания стёкол и промежутков между ними. Используют разную толщину и многослойное стекло. Попросите подтверждённые характеристики предложенной комплектации: максимальные показатели из рекламы профиля нельзя автоматически переносить на любое окно из этой системы.</p></section>\n<section id=\"section-3\"><h2>Герметичность <em class=\"heading-accent\">важна не меньше</em></h2><p>Щели ослабляют защиту от шума. Акустический стеклопакет нужно подбирать вместе с уплотнениями, фурнитурой и монтажом. После установки проверьте закрывание створок. Если шум сохраняется, обследуйте пути его проникновения, прежде чем покупать более дорогой стеклопакет.</p></section>\n<section id=\"section-4\"><h2>Заранее продумайте <em class=\"heading-accent\">свежий воздух</em></h2><p>Открытая створка пропускает уличный звук. Для спальни у дороги заранее обсудите вентиляцию при закрытом окне. Приточные устройства имеют собственные акустические характеристики; наличие клапана не гарантирует тишину и достаточный воздухообмен без правильного подбора и работающей вытяжки.</p></section>\n<section id=\"section-5\"><h2>Подготовьте вопросы <em class=\"heading-accent\">для консультации</em></h2><p>Согласуйте решение с учётом шума, вентиляции и бюджета.</p><ul><li>Какой стеклопакет предлагается и чем подтверждены его акустические свойства?</li><li>Нужна ли проверка существующих примыканий и прижима?</li><li>Как организовать проветривание, если окно выходит на дорогу?</li><li>Что именно входит в монтаж выбранной конструкции?</li></ul></section><aside class=\"article-takeaway\"><span class=\"eyebrow\">Главная мысль</span><p>Тишина зависит от всей конструкции и путей проникновения звука, включая вентиляцию.</p></aside>\n      </div>\n      </div>\n    </article>\n  </main>","article":{"slug":"okna-dlya-zashchity-ot-shuma","legacy_slug":"kak-vybrat-okna-v-kvartiru-ryadom-s-dorogoy","title":"Какие окна выбрать, если мешает шум с улицы","category":"Тишина дома","description":"Как подойти к выбору окна рядом с дорогой и почему важны стеклопакет, монтаж и проветривание.","intro":"Если за окном дорога, хочется просто заказать «самое тихое» окно. Но результат зависит от источника шума, стеклопакета, герметичности и режима вентиляции. Начать лучше с описания проблемы, а не с выбора числа камер.","sections":[{"heading":"Определите, откуда приходит звук","paragraphs":["Расскажите, какой звук мешает: поток машин, гул грузовиков или голоса. Проверьте разницу при закрытой створке. Шум может проникать через прижим, монтажные швы и вентиляцию. Иногда стоит сначала проверить существующее окно, а затем решать вопрос о замене."],"heading_accent":"откуда приходит звук"},{"heading":"Почему обычного толстого стекла недостаточно","paragraphs":["Звукоизоляция зависит от сочетания стёкол и промежутков между ними. Используют разную толщину и многослойное стекло. Попросите подтверждённые характеристики предложенной комплектации: максимальные показатели из рекламы профиля нельзя автоматически переносить на любое окно из этой системы."],"heading_accent":"толстого стекла недостаточно"},{"heading":"Герметичность важна не меньше","paragraphs":["Щели ослабляют защиту от шума. Акустический стеклопакет нужно подбирать вместе с уплотнениями, фурнитурой и монтажом. После установки проверьте закрывание створок. Если шум сохраняется, обследуйте пути его проникновения, прежде чем покупать более дорогой стеклопакет."],"heading_accent":"важна не меньше"},{"heading":"Заранее продумайте свежий воздух","paragraphs":["Открытая створка пропускает уличный звук. Для спальни у дороги заранее обсудите вентиляцию при закрытом окне. Приточные устройства имеют собственные акустические характеристики; наличие клапана не гарантирует тишину и достаточный воздухообмен без правильного подбора и работающей вытяжки."],"heading_accent":"свежий воздух"},{"heading":"Подготовьте вопросы для консультации","paragraphs":["Согласуйте решение с учётом шума, вентиляции и бюджета."],"items":["Какой стеклопакет предлагается и чем подтверждены его акустические свойства?","Нужна ли проверка существующих примыканий и прижима?","Как организовать проветривание, если окно выходит на дорогу?","Что именно входит в монтаж выбранной конструкции?"],"heading_accent":"для консультации"}],"takeaway":"Тишина зависит от всей конструкции и путей проникновения звука, включая вентиляцию.","consultation":"Сообщите, какой шум мешает и когда он сильнее всего: начнём подбор с условий вашей комнаты.","related":["kakoy-steklopaket-vybrat","ustanovka-okon-podgotovka-i-priemka"],"author":"Редакция «Спектра»","published_on":"2026-10-09","modified_on":"2026-10-11","content_kind":"original","image":{"path":"assets/solutions/thumbs/apartment-installation.webp","width":640,"height":1422,"alt":"Окно в проёме до отделки откосов","caption":"Окно в квартире с видом на город: защиту от шума подбирают по условиям за окном, а не по внешнему виду.","full_width":810,"full_height":1800},"title_accent":"если мешает шум с улицы"},"views":0}', 'Какие окна выбрать, если мешает шум с улицы — Спектр', 'Как подойти к выбору окна рядом с дорогой и почему важны стеклопакет, монтаж и проветривание.', 'https://spektr-okna.ru/articles/okna-dlya-zashchity-ot-shuma/')
ON DUPLICATE KEY UPDATE id = id;

-- /articles/okna-na-solnechnuyu-storonu/
INSERT INTO `page_articles` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/articles/okna-na-solnechnuyu-storonu/', 'Окна на солнечную сторону: как уменьшить жару в комнате', '{"main_html":"<main id=\"content\" class=\"article-detail wrap\">\n    <nav class=\"article-breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Статьи</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Солнцезащита</span></nav>\n    <article>\n      <header class=\"article-heading\"><h1>Окна на солнечную сторону: <em class=\"heading-accent\">как уменьшить жару в комнате</em></h1><div class=\"article-heading-meta\"><span><time datetime=\"2026-10-09\">09.10.2026</time></span><span>Чтение: около 2 мин</span></div></header>\n      <div class=\"article-content\">\n      <figure class=\"article-cover\"><img src=\"../../assets/solutions/roller-shutter-open.webp?v=20261024-optimized\" srcset=\"../../assets/solutions/thumbs/roller-shutter-open.webp?v=20261024-optimized 640w, ../../assets/solutions/roller-shutter-open.webp?v=20261024-optimized 1600w\" sizes=\"(max-width: 480px) calc(100vw - 32px), (max-width: 760px) calc(100vw - 40px), (max-width: 1100px) calc(100vw - 56px), (max-width: 1416px) calc(100vw - 96px), 1320px\" alt=\"Окно модульной постройки с поднятой роллетой\" width=\"1600\" height=\"1000\" fetchpriority=\"high\" decoding=\"async\"><figcaption>Наружная роллета над окном — один из способов затенения. На фото она поднята.</figcaption></figure>\n      <div class=\"article-body\"><section id=\"section-1\"><h2>Разберитесь, <em class=\"heading-accent\">когда и почему жарко</em></h2><p>Отметьте сторону света, часы перегрева и наличие тени. У больших окон солнцезащита особенно важна. Однако на температуру влияют также стены, крыша и вентиляция. Новое стекло уменьшает солнечный приток, но не заменяет охлаждение и не обещает конкретную температуру.</p></section>\n<section id=\"section-2\"><h2>Какие <em class=\"heading-accent\">свойства стекла</em> сравнивать</h2><p>Солнцезащитное стекло ограничивает поступление солнечной энергии. Мультифункциональное покрытие может сочетать эту функцию с уменьшением теплопередачи. Сравните светопропускание и солнечный фактор — долю проходящей энергии. Название покрытия само по себе не показывает, насколько светло и прохладно будет в комнате.</p><figure class=\"article-example\"><a href=\"../../assets/solutions/roller-shutter-closed.webp?v=20261024-optimized\" target=\"_blank\" rel=\"noopener\"><img src=\"../../assets/solutions/thumbs/roller-shutter-closed.webp?v=20261024-optimized\" alt=\"Оконный проём с опущенной защитной роллетой\" width=\"640\" height=\"400\" loading=\"lazy\" decoding=\"async\"></a><figcaption>Та же постройка с опущенной роллетой: наружное затенение перекрывает оконный проём.</figcaption></figure></section>\n<section id=\"section-3\"><h2>Не выбирайте <em class=\"heading-accent\">только по затемнению</em></h2><p>Тёмное стекло не всегда означает лучшую защиту от нагрева. В небольшой комнате оно может уменьшить дневной свет. Посмотрите образец и уточните оттенок, отражение и совместимость с остальными окнами фасада, особенно при замене одного стеклопакета.</p></section>\n<section id=\"section-4\"><h2>Шторы и плёнка: <em class=\"heading-accent\">что учесть</em></h2><p>Шторы регулируют яркость и приватность, но не равнозначны солнцезащитному остеклению. Подбирайте их вместе со стеклом. Перед наклеиванием плёнки проверьте совместимость: изменение поглощения тепла может вызвать неравномерный нагрев стекла. Для существующего окна обсудите допустимые варианты со специалистом.</p></section>\n<section id=\"section-5\"><h2>Что сообщить <em class=\"heading-accent\">при расчёте</em></h2><p>Для расчёта подготовьте сведения о помещении.</p><ul><li>Сторона света и часы прямого солнечного освещения.</li><li>Размеры окна, этаж и наличие наружной тени.</li><li>Насколько важны дневной свет и одинаковый вид фасада.</li><li>Есть ли кондиционер и какое затенение используется сейчас.</li></ul></section><aside class=\"article-takeaway\"><span class=\"eyebrow\">Главная мысль</span><p>Сравнивайте солнцезащиту и светопропускание вместе: комфортное окно не обязано быть тёмным.</p></aside>\n      </div>\n      </div>\n    </article>\n  </main>","article":{"slug":"okna-na-solnechnuyu-storonu","legacy_slug":"na-solnechnoy-storone-zharko-kakie-okna-vybrat-chtoby-kvartira-menshe-nagrevalas","title":"Окна на солнечную сторону: как уменьшить жару в комнате","category":"Солнцезащита","description":"Как совместить солнцезащиту, дневной свет и комфорт зимой без лишних обещаний.","intro":"Большое светлое окно радует видом, но летом комната может перегреваться. Особенно заметно это на южной и западной стороне. При выборе остекления важно уменьшить поступление солнечного тепла и при этом сохранить комфортное освещение.","sections":[{"heading":"Разберитесь, когда и почему жарко","paragraphs":["Отметьте сторону света, часы перегрева и наличие тени. У больших окон солнцезащита особенно важна. Однако на температуру влияют также стены, крыша и вентиляция. Новое стекло уменьшает солнечный приток, но не заменяет охлаждение и не обещает конкретную температуру."],"heading_accent":"когда и почему жарко"},{"heading":"Какие свойства стекла сравнивать","paragraphs":["Солнцезащитное стекло ограничивает поступление солнечной энергии. Мультифункциональное покрытие может сочетать эту функцию с уменьшением теплопередачи. Сравните светопропускание и солнечный фактор — долю проходящей энергии. Название покрытия само по себе не показывает, насколько светло и прохладно будет в комнате."],"photo":{"id":"roller-shutter-closed","title":"Роллета в закрытом положении","category":"Роллеты","alt":"Оконный проём с опущенной защитной роллетой","full":"assets/solutions/roller-shutter-closed.webp","thumb":"assets/solutions/thumbs/roller-shutter-closed.webp","width":640,"height":400,"caption":"Та же постройка с опущенной роллетой: наружное затенение перекрывает оконный проём."},"heading_accent":"свойства стекла"},{"heading":"Не выбирайте только по затемнению","paragraphs":["Тёмное стекло не всегда означает лучшую защиту от нагрева. В небольшой комнате оно может уменьшить дневной свет. Посмотрите образец и уточните оттенок, отражение и совместимость с остальными окнами фасада, особенно при замене одного стеклопакета."],"heading_accent":"только по затемнению"},{"heading":"Шторы и плёнка: что учесть","paragraphs":["Шторы регулируют яркость и приватность, но не равнозначны солнцезащитному остеклению. Подбирайте их вместе со стеклом. Перед наклеиванием плёнки проверьте совместимость: изменение поглощения тепла может вызвать неравномерный нагрев стекла. Для существующего окна обсудите допустимые варианты со специалистом."],"heading_accent":"что учесть"},{"heading":"Что сообщить при расчёте","paragraphs":["Для расчёта подготовьте сведения о помещении."],"items":["Сторона света и часы прямого солнечного освещения.","Размеры окна, этаж и наличие наружной тени.","Насколько важны дневной свет и одинаковый вид фасада.","Есть ли кондиционер и какое затенение используется сейчас."],"heading_accent":"при расчёте"}],"takeaway":"Сравнивайте солнцезащиту и светопропускание вместе: комфортное окно не обязано быть тёмным.","consultation":"Опишите, когда в комнате жарко, и пришлите фото окна — обсудим подходящие варианты остекления.","related":["kakoy-steklopaket-vybrat","kak-vybrat-plastikovye-okna-dlya-kvartiry"],"author":"Редакция «Спектра»","published_on":"2026-10-09","modified_on":"2026-10-11","content_kind":"original","image":{"path":"assets/solutions/thumbs/roller-shutter-open.webp","width":640,"height":400,"alt":"Окно модульной постройки с поднятой роллетой","caption":"Наружная роллета над окном — один из способов затенения. На фото она поднята.","full_width":1600,"full_height":1000},"title_accent":"как уменьшить жару в комнате"},"views":0}', 'Окна на солнечную сторону: как уменьшить жару в комнате — Спектр', 'Как совместить солнцезащиту, дневной свет и комфорт зимой без лишних обещаний.', 'https://spektr-okna.ru/articles/okna-na-solnechnuyu-storonu/')
ON DUPLICATE KEY UPDATE id = id;

