INSERT INTO `page_articles` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/articles/pochemu-zapotevayut-plastikovye-okna/', 'Почему запотевают пластиковые окна и что проверить сначала', '{"main_html":"<main id=\"content\" class=\"article-detail wrap\">\n    <nav class=\"article-breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Статьи</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Комфорт дома</span></nav>\n    <article>\n      <header class=\"article-heading\"><h1>Почему запотевают пластиковые окна и <em class=\"heading-accent\">что проверить сначала</em></h1><div class=\"article-heading-meta\"><span><time datetime=\"2026-10-09\">09.10.2026</time></span><span>Чтение: около 2 мин</span></div></header>\n      <div class=\"article-content\">\n      <figure class=\"article-cover\"><img src=\"../../assets/solutions/balcony-sill.webp?v=20261024-optimized\" srcset=\"../../assets/solutions/thumbs/balcony-sill.webp?v=20261024-optimized 640w, ../../assets/solutions/balcony-sill.webp?v=20261024-optimized 1350w\" sizes=\"(max-width: 480px) calc(100vw - 32px), (max-width: 760px) calc(100vw - 40px), (max-width: 1100px) calc(100vw - 56px), (max-width: 1416px) calc(100vw - 96px), 1320px\" alt=\"Балконное остекление на этапе отделки\" width=\"1350\" height=\"1800\" fetchpriority=\"high\" decoding=\"async\"><figcaption>Балкон на этапе отделки: при запотевании важно проверить вентиляцию и влажность.</figcaption></figure>\n      <div class=\"article-body\"><section id=\"section-1\"><h2>Где именно <em class=\"heading-accent\">находится влага</em></h2><p>Капли со стороны комнаты связаны с влажностью, температурой стекла и циркуляцией тепла. Влага между стёклами требует проверки герметичности стеклопакета. Наружный конденсат иногда возникает из-за охлаждения стекла и сам по себе не доказывает неисправность. Не рискуйте при наружном осмотре.</p></section>\n<section id=\"section-2\"><h2>Проверьте <em class=\"heading-accent\">источники влажности</em></h2><p>Готовка, душ, сушка белья и свежая отделка повышают влажность. При недостаточных притоке и вытяжке влага накапливается: герметичное окно не организует вентиляцию автоматически. Несколько дней наблюдайте температуру и влажность, отмечая связь запотевания с бытовыми делами и проветриванием.</p></section>\n<section id=\"section-3\"><h2>Дайте тёплому воздуху <em class=\"heading-accent\">доступ к стеклу</em></h2><p>Широкий подоконник, плотные шторы и вещи у радиатора могут мешать тёплому воздуху достигать стекла. Проверьте отопление и освободите его. Если есть холодные откосы, продувание или повторяющееся промерзание, нужно обследовать окно и примыкания.</p></section>\n<section id=\"section-4\"><h2>Когда обращаться <em class=\"heading-accent\">за осмотром</em></h2><p>Влага между стёклами, устойчивый сквозняк, мокрые откосы и обмерзание требуют осмотра. Подготовьте фотографии и сведения о погоде и температуре дома. Не заклеивайте дренаж и не усиливайте прижим наугад: это не устраняет причину конденсата.</p></section>\n<section id=\"section-5\"><h2>Порядок <em class=\"heading-accent\">первых действий</em></h2><p>Начните с простых проверок, затем обсуждайте ремонт.</p><ul><li>Определите, на какой поверхности находится вода.</li><li>Проверьте влажность, отопление и режим проветривания.</li><li>Освободите путь тёплого воздуха от радиатора к стеклу.</li><li>Если проблема сохраняется, подготовьте фото для специалиста.</li></ul></section><aside class=\"article-takeaway\"><span class=\"eyebrow\">Главная мысль</span><p>Сначала найдите место и условия появления конденсата: причины и способы решения могут быть разными.</p></aside>\n      </div>\n      </div>\n    </article>\n  </main>","article":{"slug":"pochemu-zapotevayut-plastikovye-okna","legacy_slug":"samye-tyeplye-okna-kak-vybrat-idealnuyu-konstruktsiyu","title":"Почему запотевают пластиковые окна и что проверить сначала","category":"Комфорт дома","description":"Как различить конденсат в комнате и влагу внутри стеклопакета, проверить вентиляцию и понять, когда нужен мастер.","intro":"Капли на стекле не всегда означают, что окно неисправно. Конденсат появляется, когда влажный воздух встречается с достаточно холодной поверхностью. Чтобы найти причину, сначала определите, с какой стороны находится вода и при каких условиях она появляется.","sections":[{"heading":"Где именно находится влага","paragraphs":["Капли со стороны комнаты связаны с влажностью, температурой стекла и циркуляцией тепла. Влага между стёклами требует проверки герметичности стеклопакета. Наружный конденсат иногда возникает из-за охлаждения стекла и сам по себе не доказывает неисправность. Не рискуйте при наружном осмотре."],"heading_accent":"находится влага"},{"heading":"Проверьте источники влажности","paragraphs":["Готовка, душ, сушка белья и свежая отделка повышают влажность. При недостаточных притоке и вытяжке влага накапливается: герметичное окно не организует вентиляцию автоматически. Несколько дней наблюдайте температуру и влажность, отмечая связь запотевания с бытовыми делами и проветриванием."],"heading_accent":"источники влажности"},{"heading":"Дайте тёплому воздуху доступ к стеклу","paragraphs":["Широкий подоконник, плотные шторы и вещи у радиатора могут мешать тёплому воздуху достигать стекла. Проверьте отопление и освободите его. Если есть холодные откосы, продувание или повторяющееся промерзание, нужно обследовать окно и примыкания."],"heading_accent":"доступ к стеклу"},{"heading":"Когда обращаться за осмотром","paragraphs":["Влага между стёклами, устойчивый сквозняк, мокрые откосы и обмерзание требуют осмотра. Подготовьте фотографии и сведения о погоде и температуре дома. Не заклеивайте дренаж и не усиливайте прижим наугад: это не устраняет причину конденсата."],"heading_accent":"за осмотром"},{"heading":"Порядок первых действий","paragraphs":["Начните с простых проверок, затем обсуждайте ремонт."],"items":["Определите, на какой поверхности находится вода.","Проверьте влажность, отопление и режим проветривания.","Освободите путь тёплого воздуха от радиатора к стеклу.","Если проблема сохраняется, подготовьте фото для специалиста."],"heading_accent":"первых действий"}],"takeaway":"Сначала найдите место и условия появления конденсата: причины и способы решения могут быть разными.","consultation":"Опишите, где появляется влага и при какой погоде: подскажем, какие сведения подготовить для осмотра.","related":["kakoy-steklopaket-vybrat","ukhod-za-plastikovymi-oknami"],"author":"Редакция «Спектра»","published_on":"2026-10-09","modified_on":"2026-10-11","content_kind":"original","image":{"path":"assets/solutions/thumbs/balcony-sill.webp","width":640,"height":853,"alt":"Балконное остекление на этапе отделки","caption":"Балкон на этапе отделки: при запотевании важно проверить вентиляцию и влажность.","full_width":1350,"full_height":1800},"title_accent":"что проверить сначала"},"views":0}', 'Почему запотевают пластиковые окна и что проверить сначала — Спектр', 'Как различить конденсат в комнате и влагу внутри стеклопакета, проверить вентиляцию и понять, когда нужен мастер.', 'https://spektr-okna.ru/articles/pochemu-zapotevayut-plastikovye-okna/')
ON DUPLICATE KEY UPDATE id = id;

