-- /articles/skolko-stoyat-okna-pod-klyuch/
INSERT INTO `page_articles` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/articles/skolko-stoyat-okna-pod-klyuch/', 'Сколько стоят окна под ключ: что должно входить в расчёт', '{"main_html":"<main id=\"content\" class=\"article-detail wrap\">\n    <nav class=\"article-breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Статьи</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Стоимость</span></nav>\n    <article>\n      <header class=\"article-heading\"><h1>Сколько стоят окна под ключ: <em class=\"heading-accent\">что должно входить в расчёт</em></h1><div class=\"article-heading-meta\"><span><time datetime=\"2026-10-09\">09.10.2026</time></span><span>Чтение: около 2 мин</span></div></header>\n      <div class=\"article-content\">\n      <figure class=\"article-cover\"><img src=\"../../assets/solutions/brick-house-windows.webp?v=20261024-optimized\" srcset=\"../../assets/solutions/thumbs/brick-house-windows.webp?v=20261024-optimized 640w, ../../assets/solutions/brick-house-windows.webp?v=20261024-optimized 1350w\" sizes=\"(max-width: 480px) calc(100vw - 32px), (max-width: 760px) calc(100vw - 40px), (max-width: 1100px) calc(100vw - 56px), (max-width: 1416px) calc(100vw - 96px), 1320px\" alt=\"Окна с наружными откосами и отливами\" width=\"1350\" height=\"1800\" fetchpriority=\"high\" decoding=\"async\"><figcaption>Окна, наружные откосы и отливы: уточните, какие элементы и работы включены в смету.</figcaption></figure>\n      <div class=\"article-body\"><section id=\"section-1\"><h2>От чего зависит <em class=\"heading-accent\">цена изделия</em></h2><p>Цена зависит от размеров, открывания, профиля, стеклопакета, фурнитуры и цвета. Нестандартная форма и дополнительные устройства меняют стоимость. Для сравнения запросите расчёт конкретной конструкции с одинаковыми размерами и материалами: одной площади или названия «двухстворчатое окно» недостаточно.</p></section>\n<section id=\"section-2\"><h2>Что скрывается <em class=\"heading-accent\">за словами «под ключ»</em></h2><p>Уточните письменно, включены ли доставка, подъём, демонтаж, установка, откосы и вывоз старых окон. Подоконник, отлив и сетка тоже могут оплачиваться отдельно. Если проём потребует восстановления, порядок и стоимость дополнительных работ согласуйте до их выполнения.</p></section>\n<section id=\"section-3\"><h2>Почему калькулятор даёт <em class=\"heading-accent\">только ориентир</em></h2><p>Наш калькулятор показывает примерную стоимость окна без монтажа, отлива, подоконника, сетки и других услуг. Полная смета требует профессионального замера. Попросите отдельно указать изделие, материалы и работы — так понятнее, откуда складывается итоговая сумма.</p></section>\n<section id=\"section-4\"><h2>Где <em class=\"heading-accent\">можно сэкономить</em></h2><p>Можно отказаться от ненужной ламинации или сложного открывания. Сравните два варианта под ваши задачи. Не экономьте на необходимой подготовке проёма и защите монтажного шва. Выбирая глухие части, проверьте возможность безопасного мытья наружной поверхности.</p></section>\n<section id=\"section-5\"><h2>Список <em class=\"heading-accent\">для сравнения предложений</em></h2><p>Сравнивайте сметы на одну конструкцию и уточняйте отсутствующие пункты.</p><ul><li>Совпадают ли размеры, профиль, стеклопакет и открывание?</li><li>Включены ли доставка, подъём и демонтаж?</li><li>Какие материалы и работы входят в установку и отделку?</li><li>Указаны ли дополнительные опции, итоговая сумма и порядок оплаты?</li></ul></section><aside class=\"article-takeaway\"><span class=\"eyebrow\">Главная мысль</span><p>Стоимость под ключ — это согласованная сумма за изделие, материалы и работы, а не только цена окна.</p></aside>\n      </div>\n      </div>\n    </article>\n  </main>","article":{"slug":"skolko-stoyat-okna-pod-klyuch","legacy_slug":"okna-pod-klyuch-gotovye-varianty-ostekleniya-pod-vash-byudzhet","title":"Сколько стоят окна под ключ: что должно входить в расчёт","category":"Стоимость","description":"Почему цена окна и сумма заказа отличаются, как сравнить сметы и где возможна разумная экономия.","intro":"Два предложения на одинаковый проём могут заметно различаться по цене. Причина не обязательно в наценке: в одном расчёте указано только окно, а в другом — доставка, установка и отделка. Чтобы понять бюджет, нужно сравнить весь заказ по строкам.","sections":[{"heading":"От чего зависит цена изделия","paragraphs":["Цена зависит от размеров, открывания, профиля, стеклопакета, фурнитуры и цвета. Нестандартная форма и дополнительные устройства меняют стоимость. Для сравнения запросите расчёт конкретной конструкции с одинаковыми размерами и материалами: одной площади или названия «двухстворчатое окно» недостаточно."],"heading_accent":"цена изделия"},{"heading":"Что скрывается за словами «под ключ»","paragraphs":["Уточните письменно, включены ли доставка, подъём, демонтаж, установка, откосы и вывоз старых окон. Подоконник, отлив и сетка тоже могут оплачиваться отдельно. Если проём потребует восстановления, порядок и стоимость дополнительных работ согласуйте до их выполнения."],"heading_accent":"за словами «под ключ»"},{"heading":"Почему калькулятор даёт только ориентир","paragraphs":["Наш калькулятор показывает примерную стоимость окна без монтажа, отлива, подоконника, сетки и других услуг. Полная смета требует профессионального замера. Попросите отдельно указать изделие, материалы и работы — так понятнее, откуда складывается итоговая сумма."],"heading_accent":"только ориентир"},{"heading":"Где можно сэкономить","paragraphs":["Можно отказаться от ненужной ламинации или сложного открывания. Сравните два варианта под ваши задачи. Не экономьте на необходимой подготовке проёма и защите монтажного шва. Выбирая глухие части, проверьте возможность безопасного мытья наружной поверхности."],"heading_accent":"можно сэкономить"},{"heading":"Список для сравнения предложений","paragraphs":["Сравнивайте сметы на одну конструкцию и уточняйте отсутствующие пункты."],"items":["Совпадают ли размеры, профиль, стеклопакет и открывание?","Включены ли доставка, подъём и демонтаж?","Какие материалы и работы входят в установку и отделку?","Указаны ли дополнительные опции, итоговая сумма и порядок оплаты?"],"heading_accent":"для сравнения предложений"}],"takeaway":"Стоимость под ключ — это согласованная сумма за изделие, материалы и работы, а не только цена окна.","consultation":"Подготовьте фото проёмов и перечень нужных работ — обсудим состав предварительного расчёта.","related":["kak-vybrat-plastikovye-okna-dlya-kvartiry","ustanovka-okon-podgotovka-i-priemka"],"author":"Редакция «Спектра»","published_on":"2026-10-09","modified_on":"2026-10-11","content_kind":"original","image":{"path":"assets/solutions/thumbs/brick-house-windows.webp","width":640,"height":853,"alt":"Окна с наружными откосами и отливами","caption":"Окна, наружные откосы и отливы: уточните, какие элементы и работы включены в смету.","full_width":1350,"full_height":1800},"title_accent":"что должно входить в расчёт"},"views":0}', 'Сколько стоят окна под ключ: что должно входить в расчёт — Спектр', 'Почему цена окна и сумма заказа отличаются, как сравнить сметы и где возможна разумная экономия.', 'https://spektr-okna.ru/articles/skolko-stoyat-okna-pod-klyuch/')
ON DUPLICATE KEY UPDATE id = id;

