INSERT INTO `page_articles` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/articles/teploe-ili-kholodnoe-osteklenie-balkona/', 'Тёплое или холодное остекление балкона: что выбрать', '{"main_html":"<main id=\"content\" class=\"article-detail wrap\">\n    <nav class=\"article-breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Статьи</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Балконы и лоджии</span></nav>\n    <article>\n      <header class=\"article-heading\"><h1>Тёплое или холодное остекление балкона: <em class=\"heading-accent\">что выбрать</em></h1><div class=\"article-heading-meta\"><span><time datetime=\"2026-10-09\">09.10.2026</time></span><span>Чтение: около 2 мин</span></div></header>\n      <div class=\"article-content\">\n      <figure class=\"article-cover\"><img src=\"../../assets/solutions/balcony-sill.webp?v=20261024-optimized\" srcset=\"../../assets/solutions/thumbs/balcony-sill.webp?v=20261024-optimized 640w, ../../assets/solutions/balcony-sill.webp?v=20261024-optimized 1350w\" sizes=\"(max-width: 480px) calc(100vw - 32px), (max-width: 760px) calc(100vw - 40px), (max-width: 1100px) calc(100vw - 56px), (max-width: 1416px) calc(100vw - 96px), 1320px\" alt=\"Балконное остекление на этапе отделки\" width=\"1350\" height=\"1800\" fetchpriority=\"high\" decoding=\"async\"><figcaption>Остекление балкона с подоконником: по фотографии нельзя определить, тёплая ли это система.</figcaption></figure>\n      <div class=\"article-body\"><section id=\"section-1\"><h2>Когда достаточно <em class=\"heading-accent\">холодного остекления</em></h2><p>Холодное остекление защищает от осадков и ветра. Часто используют алюминиевые системы без терморазрыва. Они не превращают балкон в отапливаемую комнату: зимой температура и влажность зависят от погоды и воздухообмена. Учтите это при хранении вещей.</p></section>\n<section id=\"section-2\"><h2>Что требуется <em class=\"heading-accent\">для тёплого пространства</em></h2><p>Для тёплого пространства выбирают подходящие стеклопакеты и профиль: ПВХ или алюминий с терморазрывом. Но тепло теряется также через пол, потолок, парапет и стены. Зимнее использование требует комплексного утепления и вентиляции, а не только новых окон.</p></section>\n<section id=\"section-3\"><h2>Оцените <em class=\"heading-accent\">основание и размеры</em></h2><p>Плита, парапет и крепления должны подходить для проекта. Вес зависит от размеров и материалов. Старое или повреждённое основание может потребовать отдельной оценки. Не выбирайте тяжёлое или панорамное остекление только по ширине проёма — нужна проверка условий установки.</p></section>\n<section id=\"section-4\"><h2>Выберите <em class=\"heading-accent\">удобное открывание</em></h2><p>Раздвижные створки экономят место, распашные дают другие возможности проветривания. Теплоизоляция зависит от конкретной системы, а не только от открывания. Учтите мебель, сушилку, потолочную отделку и доступ к наружному стеклу для безопасного обслуживания.</p></section>\n<section id=\"section-5\"><h2>Что обсудить <em class=\"heading-accent\">на замере</em></h2><p>Обсудите назначение балкона. Изменения фасада или пространства могут потребовать согласования — порядок проверяют для конкретного здания.</p><ul><li>Как балкон будет использоваться летом и зимой?</li><li>Подходит ли состояние основания для выбранного проекта?</li><li>Какие участки требуют утепления и как организовать воздухообмен?</li><li>Как открывать, мыть и обслуживать створки?</li></ul></section><aside class=\"article-takeaway\"><span class=\"eyebrow\">Главная мысль</span><p>Холодное остекление защищает от погоды; зимний комфорт требует комплексного решения для всего балкона.</p></aside>\n      </div>\n      </div>\n    </article>\n  </main>","article":{"slug":"teploe-ili-kholodnoe-osteklenie-balkona","legacy_slug":"novye-kvartiry-i-doma-kogda-ekonomiya-na-osteklenii-stanovitsya-dorogostoyashchey","title":"Тёплое или холодное остекление балкона: что выбрать","category":"Балконы и лоджии","description":"Как связать тип остекления с назначением балкона и почему одних новых окон недостаточно для тёплой комнаты.","intro":"До выбора профиля стоит ответить на один вопрос: как вы хотите пользоваться балконом? Для защиты вещей от осадков и для рабочего места зимой нужны разные проекты. Разберём, что даёт каждый вариант и какие детали нельзя пропустить.","sections":[{"heading":"Когда достаточно холодного остекления","paragraphs":["Холодное остекление защищает от осадков и ветра. Часто используют алюминиевые системы без терморазрыва. Они не превращают балкон в отапливаемую комнату: зимой температура и влажность зависят от погоды и воздухообмена. Учтите это при хранении вещей."],"heading_accent":"холодного остекления"},{"heading":"Что требуется для тёплого пространства","paragraphs":["Для тёплого пространства выбирают подходящие стеклопакеты и профиль: ПВХ или алюминий с терморазрывом. Но тепло теряется также через пол, потолок, парапет и стены. Зимнее использование требует комплексного утепления и вентиляции, а не только новых окон."],"heading_accent":"для тёплого пространства"},{"heading":"Оцените основание и размеры","paragraphs":["Плита, парапет и крепления должны подходить для проекта. Вес зависит от размеров и материалов. Старое или повреждённое основание может потребовать отдельной оценки. Не выбирайте тяжёлое или панорамное остекление только по ширине проёма — нужна проверка условий установки."],"heading_accent":"основание и размеры"},{"heading":"Выберите удобное открывание","paragraphs":["Раздвижные створки экономят место, распашные дают другие возможности проветривания. Теплоизоляция зависит от конкретной системы, а не только от открывания. Учтите мебель, сушилку, потолочную отделку и доступ к наружному стеклу для безопасного обслуживания."],"heading_accent":"удобное открывание"},{"heading":"Что обсудить на замере","paragraphs":["Обсудите назначение балкона. Изменения фасада или пространства могут потребовать согласования — порядок проверяют для конкретного здания."],"items":["Как балкон будет использоваться летом и зимой?","Подходит ли состояние основания для выбранного проекта?","Какие участки требуют утепления и как организовать воздухообмен?","Как открывать, мыть и обслуживать створки?"],"heading_accent":"на замере"}],"takeaway":"Холодное остекление защищает от погоды; зимний комфорт требует комплексного решения для всего балкона.","consultation":"Покажите фотографии балкона и расскажите, как хотите им пользоваться: обсудим варианты и вопросы для замера.","related":["skolko-stoyat-okna-pod-klyuch","kakoy-steklopaket-vybrat"],"author":"Редакция «Спектра»","published_on":"2026-10-09","modified_on":"2026-10-11","content_kind":"original","image":{"path":"assets/solutions/thumbs/balcony-sill.webp","width":640,"height":853,"alt":"Балконное остекление на этапе отделки","caption":"Остекление балкона с подоконником: по фотографии нельзя определить, тёплая ли это система.","full_width":1350,"full_height":1800},"title_accent":"что выбрать"},"views":0}', 'Тёплое или холодное остекление балкона: что выбрать — Спектр', 'Как связать тип остекления с назначением балкона и почему одних новых окон недостаточно для тёплой комнаты.', 'https://spektr-okna.ru/articles/teploe-ili-kholodnoe-osteklenie-balkona/')
ON DUPLICATE KEY UPDATE id = id;

