INSERT INTO `page_articles` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/articles/ukhod-za-plastikovymi-oknami/', 'Уход за пластиковыми окнами: мытьё, уплотнители и фурнитура', '{"main_html":"<main id=\"content\" class=\"article-detail wrap\">\n    <nav class=\"article-breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Статьи</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Уход за окнами</span></nav>\n    <article>\n      <header class=\"article-heading\"><h1>Уход за пластиковыми окнами: <em class=\"heading-accent\">мытьё, уплотнители и фурнитура</em></h1><div class=\"article-heading-meta\"><span><time datetime=\"2026-10-09\">09.10.2026</time></span><span>Чтение: около 2 мин</span></div></header>\n      <div class=\"article-content\">\n      <figure class=\"article-cover\"><img src=\"../../assets/solutions/window-with-screen.webp?v=20261024-optimized\" srcset=\"../../assets/solutions/thumbs/window-with-screen.webp?v=20261024-optimized 640w, ../../assets/solutions/window-with-screen.webp?v=20261024-optimized 1350w\" sizes=\"(max-width: 480px) calc(100vw - 32px), (max-width: 760px) calc(100vw - 40px), (max-width: 1100px) calc(100vw - 56px), (max-width: 1416px) calc(100vw - 96px), 1320px\" alt=\"Белое окно с сеткой на открывающейся створке\" width=\"1350\" height=\"1800\" fetchpriority=\"high\" decoding=\"async\"><figcaption>Окно с москитной сеткой: сетку снимают для очистки, а профиль и уплотнители моют отдельно.</figcaption></figure>\n      <div class=\"article-body\"><section id=\"section-1\"><h2>Как мыть <em class=\"heading-accent\">стекло и профиль</em></h2><p>Сначала очистите раму, затем стекло. Используйте мягкую ткань и подходящее нейтральное средство; удобнее мыть в тени. Не применяйте абразивы и агрессивные растворители без разрешения производителя. Для ламинации и строительных загрязнений следуйте отдельным рекомендациям.</p></section>\n<section id=\"section-2\"><h2>Не забывайте про <em class=\"heading-accent\">уплотнения и дренаж</em></h2><p>Удаляйте пыль с уплотнений, проверяйте разрывы и положение в пазах. Средства ухода выбирайте по инструкции. Очищайте доступный дренаж, не повреждая элементы, и не закрывайте отверстия герметиком. Если вода остаётся или попадает внутрь, нужна проверка.</p></section>\n<section id=\"section-3\"><h2>Обслуживайте фурнитуру <em class=\"heading-accent\">по инструкции</em></h2><p>Смазывайте только предусмотренные узлы рекомендованным составом и с указанной периодичностью. Растительное масло не подходит. Если створка цепляет раму или ручка идёт туго, не прикладывайте силу и не меняйте прижим наугад — сначала выясните причину.</p></section>\n<section id=\"section-4\"><h2>Нужен ли обязательный <em class=\"heading-accent\">«зимний режим»</em></h2><p>Сезонное переключение прижима не является правилом для всех окон. Излишнее сжатие ускоряет износ уплотнений. Перед зимой проверьте закрывание и продувание; исправное окно не нужно регулировать только из-за календаря. Ориентируйтесь на инструкцию своей фурнитуры.</p></section>\n<section id=\"section-5\"><h2>Короткий список <em class=\"heading-accent\">для регулярного осмотра</em></h2><p>Проверяйте окно по инструкции. При наружном мытье не вставайте на подоконник и не опирайтесь на сетку.</p><ul><li>Стекло и профиль чистые, без следов неподходящих средств.</li><li>Уплотнения целые, доступный дренаж не забит.</li><li>Створка открывается плавно, ручка работает без чрезмерного усилия.</li><li>Замки и ограничители исправны; обнаруженные проблемы записаны для мастера.</li></ul></section><aside class=\"article-takeaway\"><span class=\"eyebrow\">Главная мысль</span><p>Мягкое мытьё и обслуживание по инструкции полезнее агрессивных средств и регулировки наугад.</p></aside>\n      </div>\n      </div>\n    </article>\n  </main>","article":{"slug":"ukhod-za-plastikovymi-oknami","legacy_slug":"idealnaya-chistota-kak-pravilno-myt-okna-bez-razvodov-i-tsarapin","title":"Уход за пластиковыми окнами: мытьё, уплотнители и фурнитура","category":"Уход за окнами","description":"Как ухаживать за окном без царапин, что проверять регулярно и когда регулировку лучше поручить мастеру.","intro":"Окну нужны не только чистые стёкла. Уплотнения, дренаж и подвижные механизмы тоже требуют внимания. Регулярный простой уход помогает заметить проблему вовремя, а правила конкретного производителя подскажут подходящие средства и порядок обслуживания.","sections":[{"heading":"Как мыть стекло и профиль","paragraphs":["Сначала очистите раму, затем стекло. Используйте мягкую ткань и подходящее нейтральное средство; удобнее мыть в тени. Не применяйте абразивы и агрессивные растворители без разрешения производителя. Для ламинации и строительных загрязнений следуйте отдельным рекомендациям."],"heading_accent":"стекло и профиль"},{"heading":"Не забывайте про уплотнения и дренаж","paragraphs":["Удаляйте пыль с уплотнений, проверяйте разрывы и положение в пазах. Средства ухода выбирайте по инструкции. Очищайте доступный дренаж, не повреждая элементы, и не закрывайте отверстия герметиком. Если вода остаётся или попадает внутрь, нужна проверка."],"heading_accent":"уплотнения и дренаж"},{"heading":"Обслуживайте фурнитуру по инструкции","paragraphs":["Смазывайте только предусмотренные узлы рекомендованным составом и с указанной периодичностью. Растительное масло не подходит. Если створка цепляет раму или ручка идёт туго, не прикладывайте силу и не меняйте прижим наугад — сначала выясните причину."],"heading_accent":"по инструкции"},{"heading":"Нужен ли обязательный «зимний режим»","paragraphs":["Сезонное переключение прижима не является правилом для всех окон. Излишнее сжатие ускоряет износ уплотнений. Перед зимой проверьте закрывание и продувание; исправное окно не нужно регулировать только из-за календаря. Ориентируйтесь на инструкцию своей фурнитуры."],"heading_accent":"«зимний режим»"},{"heading":"Короткий список для регулярного осмотра","paragraphs":["Проверяйте окно по инструкции. При наружном мытье не вставайте на подоконник и не опирайтесь на сетку."],"items":["Стекло и профиль чистые, без следов неподходящих средств.","Уплотнения целые, доступный дренаж не забит.","Створка открывается плавно, ручка работает без чрезмерного усилия.","Замки и ограничители исправны; обнаруженные проблемы записаны для мастера."],"heading_accent":"для регулярного осмотра"}],"takeaway":"Мягкое мытьё и обслуживание по инструкции полезнее агрессивных средств и регулировки наугад.","consultation":"Если окно стало закрываться иначе или появилась влага, опишите симптомы — обсудим, когда нужен осмотр.","related":["pochemu-zapotevayut-plastikovye-okna","bezopasnye-okna-dlya-detey"],"author":"Редакция «Спектра»","published_on":"2026-10-09","modified_on":"2026-10-11","content_kind":"original","image":{"path":"assets/solutions/thumbs/window-with-screen.webp","width":640,"height":853,"alt":"Белое окно с сеткой на открывающейся створке","caption":"Окно с москитной сеткой: сетку снимают для очистки, а профиль и уплотнители моют отдельно.","full_width":1350,"full_height":1800},"title_accent":"мытьё, уплотнители и фурнитура"},"views":0}', 'Уход за пластиковыми окнами: мытьё, уплотнители и фурнитура — Спектр', 'Как ухаживать за окном без царапин, что проверять регулярно и когда регулировку лучше поручить мастеру.', 'https://spektr-okna.ru/articles/ukhod-za-plastikovymi-oknami/')
ON DUPLICATE KEY UPDATE id = id;

-- /articles/ustanovka-okon-podgotovka-i-priemka/
INSERT INTO `page_articles` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/articles/ustanovka-okon-podgotovka-i-priemka/', 'Установка окон: как подготовиться и что проверить при приёмке', '{"main_html":"<main id=\"content\" class=\"article-detail wrap\">\n    <nav class=\"article-breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Статьи</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Монтаж</span></nav>\n    <article>\n      <header class=\"article-heading\"><h1>Установка окон: <em class=\"heading-accent\">как подготовиться и что проверить при приёмке</em></h1><div class=\"article-heading-meta\"><span><time datetime=\"2026-10-09\">09.10.2026</time></span><span>Чтение: около 2 мин</span></div></header>\n      <div class=\"article-content\">\n      <figure class=\"article-cover\"><img src=\"../../assets/solutions/frame-house-window.webp?v=20261024-optimized\" srcset=\"../../assets/solutions/thumbs/frame-house-window.webp?v=20261024-optimized 640w, ../../assets/solutions/frame-house-window.webp?v=20261024-optimized 1350w\" sizes=\"(max-width: 480px) calc(100vw - 32px), (max-width: 760px) calc(100vw - 40px), (max-width: 1100px) calc(100vw - 56px), (max-width: 1416px) calc(100vw - 96px), 1320px\" alt=\"Белое окно с москитной сеткой до отделки фасада\" width=\"1350\" height=\"1800\" fetchpriority=\"high\" decoding=\"async\"><figcaption>Окно до отделки фасада: монтажный шов предстоит закрыть и защитить.</figcaption></figure>\n      <div class=\"article-body\"><section id=\"section-1\"><h2>Замер — это <em class=\"heading-accent\">больше, чем ширина и высота</em></h2><p>Примерные размеры подходят для предварительного расчёта. Для заказа нужен профессиональный замер с проверкой геометрии, основания и примыканий. Согласуйте открывание, подоконник, откосы и дополнительные элементы. Покажите мебель и шторы, которые могут мешать створкам.</p><figure class=\"article-example\"><a href=\"../../assets/solutions/apartment-installation.webp?v=20261024-optimized\" target=\"_blank\" rel=\"noopener\"><img src=\"../../assets/solutions/thumbs/apartment-installation.webp?v=20261024-optimized\" alt=\"Окно в проёме до отделки откосов\" width=\"640\" height=\"1422\" loading=\"lazy\" decoding=\"async\"></a><figcaption>Пример монтажа в квартире до отделки откосов. Состав последующих работ согласуют при заказе.</figcaption></figure></section>\n<section id=\"section-2\"><h2>Согласуйте <em class=\"heading-accent\">весь объём работ</em></h2><p>Уточните доставку, подъём, демонтаж, монтаж, отделку и вывоз старых окон. При слабом основании дополнительные работы и цену согласуют до выполнения. Отдельно узнайте, когда завершат откосы: это может быть позже дня установки.</p></section>\n<section id=\"section-3\"><h2>Подготовьте <em class=\"heading-accent\">комнату</em></h2><p>Освободите подоконник и проход, снимите шторы, уберите хрупкие вещи. Защитите мебель, технику и пол. Согласуйте место для инструментов и старых окон. Во время монтажа ограничьте доступ детей и животных, уточните последовательность работ и необходимость вашего присутствия.</p></section>\n<section id=\"section-4\"><h2>На что смотреть <em class=\"heading-accent\">при приёмке</em></h2><p>С мастером проверьте комплектацию, поверхности и открывание без заеданий. Уточните крепление и защиту примыканий: пена не заменяет крепёж и защиту от внешних воздействий. Скрытые работы нельзя проверить только по готовому окну — полезны фотографии этапов и документы.</p></section>\n<section id=\"section-5\"><h2>Что получить <em class=\"heading-accent\">после установки</em></h2><p>Зафиксируйте замечания и договоритесь об их устранении. Получите документы и инструкции.</p><ul><li>Описание комплектации и выполненных работ.</li><li>Инструкции по открыванию, уходу и безопасному использованию.</li><li>Условия гарантии на изделия и работы, контакты для обращения.</li><li>Понятный порядок завершения отделки, если она выполняется позже.</li></ul></section><aside class=\"article-takeaway\"><span class=\"eyebrow\">Главная мысль</span><p>Качественная приёмка начинается с понятной сметы и заканчивается проверкой окна вместе с мастером.</p></aside>\n      </div>\n      </div>\n    </article>\n  </main>","article":{"slug":"ustanovka-okon-podgotovka-i-priemka","legacy_slug":"pravila-montazha-okon-po-gostu-kak-proverit-chto-rabotu-sdelali-gramotno","title":"Установка окон: как подготовиться и что проверить при приёмке","category":"Монтаж","description":"Понятный порядок от замера до проверки створок, швов и отделки после установки.","intro":"Комфорт зависит не только от выбранного окна, но и от того, как оно установлено. Покупателю не нужно самостоятельно выполнять монтаж: полезнее заранее согласовать состав работ и понимать, что проверить вместе с мастером по их завершении.","sections":[{"heading":"Замер — это больше, чем ширина и высота","paragraphs":["Примерные размеры подходят для предварительного расчёта. Для заказа нужен профессиональный замер с проверкой геометрии, основания и примыканий. Согласуйте открывание, подоконник, откосы и дополнительные элементы. Покажите мебель и шторы, которые могут мешать створкам."],"photo":{"id":"apartment-installation","title":"Монтаж окна в квартире","category":"Монтаж","alt":"Окно в проёме до отделки откосов","full":"assets/solutions/apartment-installation.webp","thumb":"assets/solutions/thumbs/apartment-installation.webp","width":640,"height":1422,"caption":"Пример монтажа в квартире до отделки откосов. Состав последующих работ согласуют при заказе."},"heading_accent":"больше, чем ширина и высота"},{"heading":"Согласуйте весь объём работ","paragraphs":["Уточните доставку, подъём, демонтаж, монтаж, отделку и вывоз старых окон. При слабом основании дополнительные работы и цену согласуют до выполнения. Отдельно узнайте, когда завершат откосы: это может быть позже дня установки."],"heading_accent":"весь объём работ"},{"heading":"Подготовьте комнату","paragraphs":["Освободите подоконник и проход, снимите шторы, уберите хрупкие вещи. Защитите мебель, технику и пол. Согласуйте место для инструментов и старых окон. Во время монтажа ограничьте доступ детей и животных, уточните последовательность работ и необходимость вашего присутствия."],"heading_accent":"комнату"},{"heading":"На что смотреть при приёмке","paragraphs":["С мастером проверьте комплектацию, поверхности и открывание без заеданий. Уточните крепление и защиту примыканий: пена не заменяет крепёж и защиту от внешних воздействий. Скрытые работы нельзя проверить только по готовому окну — полезны фотографии этапов и документы."],"heading_accent":"при приёмке"},{"heading":"Что получить после установки","paragraphs":["Зафиксируйте замечания и договоритесь об их устранении. Получите документы и инструкции."],"items":["Описание комплектации и выполненных работ.","Инструкции по открыванию, уходу и безопасному использованию.","Условия гарантии на изделия и работы, контакты для обращения.","Понятный порядок завершения отделки, если она выполняется позже."],"heading_accent":"после установки"}],"takeaway":"Качественная приёмка начинается с понятной сметы и заканчивается проверкой окна вместе с мастером.","consultation":"Уточните состав заказа и подготовку помещения в выбранном офисе до даты установки.","related":["skolko-stoyat-okna-pod-klyuch","ukhod-za-plastikovymi-oknami"],"author":"Редакция «Спектра»","published_on":"2026-10-09","modified_on":"2026-10-11","content_kind":"original","image":{"path":"assets/solutions/thumbs/frame-house-window.webp","width":640,"height":853,"alt":"Белое окно с москитной сеткой до отделки фасада","caption":"Окно до отделки фасада: монтажный шов предстоит закрыть и защитить.","full_width":1350,"full_height":1800},"title_accent":"как подготовиться и что проверить при приёмке"},"views":0}', 'Установка окон: как подготовиться и что проверить при приёмке — Спектр', 'Понятный порядок от замера до проверки створок, швов и отделки после установки.', 'https://spektr-okna.ru/articles/ustanovka-okon-podgotovka-i-priemka/')
ON DUPLICATE KEY UPDATE id = id;

