INSERT INTO `page_calculator` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/calculator/', 'Рассчитайте стоимость окна', '{"main_html":"<main class=\"wrap calculator-page-main\">\n    <nav class=\"breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../\">Главная</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Калькулятор</span></nav>\n    <header class=\"calculator-page-heading section-copy\">\n      <h1 id=\"calculatorTitle\">Рассчитайте <em class=\"heading-accent\">стоимость окна</em></h1>\n      <p>Укажите размеры и комплектацию. Стоимость обновится автоматически.</p>\n    </header>\n        <section class=\"calculator calculator-detailed\" aria-labelledby=\"calculatorTitle\">\n          <div class=\"calculator-content\">\n            <div class=\"calculator-fields\">\n              <fieldset class=\"calc-wide calc-sashes\"><legend><span class=\"calc-step-number\">1</span> Количество створок</legend>\n                <p class=\"calc-help\">Выберите количество вертикальных секций окна.</p>\n                <div class=\"sash-presets\" role=\"group\" aria-label=\"Выбрать количество створок\">\n                  <button type=\"button\" data-sashes=\"1\" aria-pressed=\"false\">1</button>\n                  <button type=\"button\" data-sashes=\"2\" aria-pressed=\"true\">2</button>\n                  <button type=\"button\" data-sashes=\"3\" aria-pressed=\"false\">3</button>\n                  <button type=\"button\" data-sashes=\"4\" aria-pressed=\"false\">4</button>\n                  <button type=\"button\" data-sashes=\"5\" aria-pressed=\"false\">5</button>\n                  <button type=\"button\" data-sashes=\"6\" aria-pressed=\"false\">6</button>\n                  <button type=\"button\" data-sashes=\"7\" aria-pressed=\"false\">7</button>\n                  <button type=\"button\" data-sashes=\"8\" aria-pressed=\"false\">8</button>\n                  <button type=\"button\" data-sashes=\"9\" aria-pressed=\"false\">9</button>\n                  <button type=\"button\" data-sashes=\"10\" aria-pressed=\"false\">10</button>\n                </div>\n                <label for=\"sashesInput\">Своё количество</label>\n                <input id=\"sashesInput\" type=\"number\" min=\"1\" step=\"1\" value=\"2\" inputmode=\"numeric\" required>\n              </fieldset>\n              <fieldset class=\"calc-wide\"><legend><span class=\"calc-step-number\">2</span> Открывание</legend>\n                <label for=\"openingInput\">Сколько створок будут открываться?</label>\n                <select id=\"openingInput\" aria-describedby=\"openingHelp sashSummary\">\n                  <option value=\"0\">0 — все глухие</option><option value=\"1\" selected>1</option><option value=\"2\">2 — все поворотно-откидные</option>\n                </select>\n                <input id=\"customOpeningInput\" type=\"number\" min=\"0\" step=\"1\" value=\"1\" inputmode=\"numeric\" aria-label=\"Количество поворотно-откидных створок\" aria-describedby=\"openingHelp sashSummary\" hidden disabled>\n                <p class=\"calc-help\" id=\"openingHelp\">Выбранные створки открываются и откидываются для проветривания. Остальные не открываются.</p>\n                <p class=\"sash-summary\" id=\"sashSummary\" aria-live=\"polite\"></p>\n              </fieldset>\n              <fieldset class=\"calc-wide\"><legend><span class=\"calc-step-number\">3</span> Стеклопакет</legend>\n                <label for=\"chambersInput\">Количество камер</label>\n                <select id=\"chambersInput\" aria-describedby=\"chambersHelp\"><option value=\"1\">1 камера — 2 стекла</option><option value=\"2\">2 камеры — 3 стекла</option><option value=\"3\">3 камеры — 4 стекла</option><option value=\"4\">4 камеры — 5 стёкол</option></select>\n                <p class=\"calc-help\" id=\"chambersHelp\">Камера — промежуток между стёклами. Не путайте с камерами профиля.</p>\n              </fieldset>\n              <fieldset class=\"calc-wide\"><legend><span class=\"calc-step-number\">4</span> Размеры окна</legend><div class=\"calc-pair\">\n                <label>Ширина, мм<input id=\"widthInput\" type=\"number\" min=\"1\" step=\"1\" value=\"1300\" inputmode=\"numeric\" required></label>\n                <label>Высота, мм<input id=\"heightInput\" type=\"number\" min=\"1\" step=\"1\" value=\"1400\" inputmode=\"numeric\" required></label>\n              </div><p class=\"calc-help\">Общий размер рамы в миллиметрах. Например, 130 см = 1300 мм.</p></fieldset>\n              <fieldset class=\"calc-wide\"><legend><span class=\"calc-step-number\">5</span> Профиль</legend><div class=\"calc-pair\">\n                <label>Название профиля<select id=\"profileInput\"><option value=\"Prowins\">Prowins</option><option value=\"Elex\" selected>Elex</option></select></label>\n                <label>Монтажная глубина<select id=\"profileWidthInput\"><option value=\"58\">58 мм</option><option value=\"70\" selected>70 мм</option></select></label>\n              </div></fieldset>\n            </div>\n            <aside class=\"calculator-summary\" aria-label=\"Ваше окно и стоимость\">\n              <div class=\"calc-preview\">\n                <div class=\"calc-preview-heading\"><h2>Ваше <em class=\"heading-accent\">окно</em></h2><span id=\"calcPreviewSize\">1300 × 1400 мм</span></div>\n                <svg id=\"calcWindowPreview\" viewBox=\"0 0 400 280\" role=\"img\" aria-label=\"Условная схема окна с двумя створками\"><rect x=\"100\" y=\"28\" width=\"200\" height=\"224\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"5\"/><path d=\"M200 28v224M108 36h84v208h-84zM208 36h84v208h-84zM108 36l84 104-84 104\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>\n                <p class=\"calc-preview-note\" id=\"calcPreviewNote\">Условная схема. Расположение створок уточним при заказе.</p>\n              </div>\n              <div aria-live=\"polite\" aria-atomic=\"true\">\n                <p id=\"calcError\" class=\"calc-error\" hidden></p>\n                <div class=\"calculator-result\"><span>Примерная стоимость окна</span><b id=\"calcPrice\">—</b></div>\n              </div>\n              <p class=\"calc-exclusions\">Монтаж, доставка, подоконник, отлив и москитная сетка — отдельно. Итоговую стоимость согласуем после замера.</p>\n              <details class=\"calculator-price-details\"><summary>Как получилась сумма</summary><span id=\"calcTariff\" class=\"calc-tariff\"></span><p id=\"calcBreakdown\" class=\"calc-help\"></p></details>\n              <a class=\"page-end-action\" href=\"tel:+79895175699\" aria-label=\"Уточнить стоимость: 8 (989) 517-56-99\"><svg class=\"page-end-action-icon\" viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"m7 3 3 5-2.5 2.5a15 15 0 0 0 6 6L16 14l5 3c0 3-2 4-4 4C10 20 4 14 3 7c0-2 1-4 4-4Z\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg><span class=\"page-end-action-copy\"><span>Уточнить стоимость</span><strong>8 (989) 517-56-99</strong></span><span class=\"page-end-action-arrow\" aria-hidden=\"true\">↗</span></a>\n              <noscript>Для расчёта включите JavaScript или позвоните менеджеру: 8 (989) 517-56-99.</noscript>\n            </aside>\n          </div>\n        </section>\n    <a class=\"secondary-link calculator-back\" href=\"../#calculator\" data-calculator-link>Быстрый расчёт на главной <span aria-hidden=\"true\">↗</span></a>\n  </main>"}', 'Калькулятор пластиковых окон — расчёт стоимости | Спектр', 'Рассчитайте примерную цену пластикового окна по размерам, профилю и стеклопакету. Монтаж, доставка и дополнительные услуги рассчитываются отдельно.', 'https://spektr-okna.ru/calculator/')
ON DUPLICATE KEY UPDATE id = id;

