INSERT INTO `page_catalog` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/catalog/okna/', 'Пластиковые окна Под ваше пространство', '{"main_html":"<main id=\"content\" class=\"wrap local-main\">\n  <nav class=\"breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Каталог</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Окна ПВХ</span></nav>\n  <header class=\"local-heading\"><h1>Пластиковые окна<br><em class=\"heading-accent\">Под ваше пространство</em></h1><p>Оконные системы REHAU и PRO WINS для квартиры, дома и балконного блока. Производим окна по размерам заказчика с 2004 года. Выберите профиль и комплектацию под ваши задачи.</p><div class=\"local-actions\"><a class=\"local-button\" href=\"../?category=windows\">Открыть каталог окон</a><a class=\"local-text-link\" href=\"../../#request\">Получить расчёт ↗</a></div></header>\n  <section class=\"local-section\"><h2>Какую <em class=\"heading-accent\">оконную систему</em> выбрать?</h2><div class=\"local-grid\"><article><h3>Окна REHAU</h3><p>В каталоге представлены Delight Design, Grazio, Intelio и Blitz New. Профиль сравнивайте вместе со стеклопакетом, фурнитурой и схемой открывания.</p><a href=\"../?category=windows&amp;collection=rehau\">Посмотреть окна REHAU ↗</a></article><article><h3>Окна PRO WINS</h3><p>Профильные системы с монтажной глубиной 58 и 70 мм. Подбор зависит от размеров проёма, назначения помещения и требований к остеклению.</p><a href=\"../?category=windows&amp;collection=pro\">Посмотреть PRO WINS ↗</a></article><article><h3>Комплектации «Спектр»</h3><p>«Эконом», «Оптимальный», «Комфорт», «Энерго» и «Элит». Сравните состав каждой комплектации; дополнительные опции согласуем при расчёте.</p><a href=\"../?category=windows&amp;collection=ready\">Сравнить комплектации ↗</a></article><article><h3>Нестандартные окна</h3><p>Арочные конструкции и окна для проёмов необычной формы. Возможность изготовления, размеры и открывание уточняются для конкретного объекта.</p><a href=\"../?category=windows&amp;collection=custom\">Индивидуальные решения ↗</a></article></div></section>\n  <section class=\"local-section\"><h2>Цена пластикового окна <em class=\"heading-accent\">с установкой</em></h2><p class=\"local-lead\">Ориентир в каталоге — от 6 500 ₽ / м² за базовое изделие без монтажа и доставки. Полную стоимость согласуем после замера: она зависит от профиля, стеклопакета, створок и выбранных работ.</p><ul class=\"local-list\"><li>Само окно: размеры, профиль, стеклопакет и фурнитура.</li><li>Работы: доставка, демонтаж старой конструкции и установка.</li><li>Дополнения: подоконник, отлив, сетка и отделка откосов — по согласованию.</li></ul><div class=\"local-actions\"><a class=\"local-button\" href=\"../../calculator/\">Рассчитать изделие</a><a href=\"../../ustanovka-okon/\">Что учесть при установке ↗</a></div></section>\n  <section class=\"local-section\"><h2>Где купить <em class=\"heading-accent\">окна «Спектр»?</em></h2><nav class=\"local-cities\" aria-label=\"Офисы по городам\"><a href=\"../../contacts/rostov-na-donu/\">Ростов-на-Дону ↗</a><a href=\"../../contacts/azov/\">Азов ↗</a><a href=\"../../contacts/bataysk/\">Батайск ↗</a><a href=\"../../contacts/eysk/\">Ейск ↗</a><a href=\"../../contacts/kuleshovka/\">Кулешовка ↗</a></nav><p>С образцами и комплектациями поможем разобраться в одном из шести офисов. Запрос на расчёт можно оставить и на сайте.</p></section>\n  <nav class=\"local-related\" aria-label=\"Выбор и заказ окон\"><a href=\"../../catalog/okna/\">Окна ПВХ и оконные системы ↗</a><a href=\"../../ustanovka-okon/\">Установка окон ↗</a><a href=\"../../calculator/\">Калькулятор стоимости ↗</a><a href=\"../../solutions/\">Примеры работ ↗</a></nav>\n</main>"}', 'Купить пластиковые окна ПВХ — оконные системы и цены | Спектр', 'Пластиковые окна REHAU и PRO WINS от завода «Спектр». Комплектации, примерные цены от 6 500 ₽/м² без монтажа, выбор стеклопакета и расчёт установки.', 'https://spektr-okna.ru/catalog/okna/')
ON DUPLICATE KEY UPDATE id = id;

-- /contacts/azov/
INSERT INTO `page_contacts` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/contacts/azov/', 'Пластиковые окна в Азове', '{"main_html":"<main id=\"content\" class=\"wrap local-main\">\n    <nav class=\"breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Филиалы</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Азов</span></nav>\n    <header class=\"local-heading\"><h1>Пластиковые окна<br><em class=\"heading-accent\">в Азове</em></h1><p>Офис «Спектр» в Азове находится на улице Ленина, 66. Здесь можно обсудить окна для квартиры, балконный блок или остекление частного дома.</p><div class=\"local-actions\"><a class=\"local-button\" href=\"../../#request\">Оставить заявку</a><a class=\"local-text-link\" href=\"#offices\">Адреса и телефоны ↗</a></div></header>\n    <section id=\"offices\" class=\"local-section\"><h2>Где купить <em class=\"heading-accent\">окна в Азове?</em></h2><p class=\"local-lead\">Азовский офис работает с 08:00 и принимает посетителей по субботам и воскресеньям до 14:00. Для предварительного обсуждения заказа доступны два телефона.</p><div class=\"local-offices\"><article class=\"local-office\" id=\"azov\"><a href=\"https://yandex.ru/maps/?text=%D0%90%D0%B7%D0%BE%D0%B2%2C%20%D0%B3.%20%D0%90%D0%B7%D0%BE%D0%B2%2C%20%D1%83%D0%BB.%20%D0%9B%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0%2C%2066\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"../../contacts/assets/azov.webp\" width=\"1260\" height=\"810\" loading=\"lazy\" decoding=\"async\" alt=\"Карта: Азов, г. Азов, ул. Ленина, 66\"></a><div><h3>г. Азов, ул. Ленина, 66</h3><p>Азов · Ростовская область</p><p>Пн–Пт: 08:00–17:00<br>Сб–Вс: 08:00–14:00</p><div class=\"local-actions\"><a class=\"local-button\" href=\"tel:+79895175699\">8 (989) 517-56-99</a><a class=\"local-button\" href=\"tel:+79885636555\">8 (988) 563-65-55</a><a class=\"local-text-link\" href=\"https://yandex.ru/maps/?text=%D0%90%D0%B7%D0%BE%D0%B2%2C%20%D0%B3.%20%D0%90%D0%B7%D0%BE%D0%B2%2C%20%D1%83%D0%BB.%20%D0%9B%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0%2C%2066\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть карту ↗</a></div></div></article></div></section>\n    <section class=\"local-section\"><h2>От выбора окна — <em class=\"heading-accent\">к установке</em></h2><div class=\"local-grid\"><div><h3>Что можно заказать</h3><p>Пластиковые окна ПВХ из профилей REHAU и PRO WINS, балконные блоки и остекление по индивидуальным размерам. Комплектацию подбираем под помещение, шум с улицы и нужное открывание.</p><a href=\"../../catalog/okna/\">Посмотреть оконные системы ↗</a></div><div><h3>Как получить цену с установкой</h3><p>Пришлите фото и примерные размеры, укажите адрес объекта. После замера согласуем изделие, монтаж и дополнительные работы. Уточните, нужны ли демонтаж, подоконник, отлив, сетка и откосы.</p><a href=\"../../ustanovka-okon/\">Как проходит установка ↗</a></div></div></section>\n    <section class=\"local-section\"><h2>Сколько стоят <em class=\"heading-accent\">пластиковые окна?</em></h2><p class=\"local-lead\">В каталоге указан ориентир на изделие — от 6 500 ₽ / м² без монтажа и доставки. Это не цена окна с установкой: итог зависит от размеров, профиля, стеклопакета, числа створок и состава работ.</p><a class=\"local-button\" href=\"../../calculator/\">Рассчитать своё окно</a></section>\n    <nav class=\"local-related\" aria-label=\"Выбор и заказ окон\"><a href=\"../../catalog/okna/\">Окна ПВХ и оконные системы ↗</a><a href=\"../../ustanovka-okon/\">Установка окон ↗</a><a href=\"../../calculator/\">Калькулятор стоимости ↗</a><a href=\"../../solutions/\">Примеры работ ↗</a></nav>\n  </main>","branch_ids":["azov"]}', 'Пластиковые окна в Азове — купить с установкой | Спектр', 'Окна ПВХ «Спектр» в Азове: г. Азов, ул. Ленина, 66, телефоны и часы работы. Подбор оконных систем, замер и расчёт стоимости с установкой.', 'https://spektr-okna.ru/contacts/azov/')
ON DUPLICATE KEY UPDATE id = id;

