INSERT INTO `page_contacts` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/contacts/bataysk/', 'Пластиковые окна в Батайске', '{"main_html":"<main id=\"content\" class=\"wrap local-main\">\n    <nav class=\"breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Филиалы</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Батайск</span></nav>\n    <header class=\"local-heading\"><h1>Пластиковые окна<br><em class=\"heading-accent\">в Батайске</em></h1><p>Салон «Спектр» в Батайске расположен по адресу: улица М. Горького, 152 / улица Куйбышева, 143. Приходите с фото проёма и пожеланиями к новым окнам.</p><div class=\"local-actions\"><a class=\"local-button\" href=\"../../#request\">Оставить заявку</a><a class=\"local-text-link\" href=\"#offices\">Адреса и телефоны ↗</a></div></header>\n    <section id=\"offices\" class=\"local-section\"><h2>Где купить <em class=\"heading-accent\">окна в Батайске?</em></h2><p class=\"local-lead\">В карточке указан адрес здания с двух улиц — М. Горького и Куйбышева. Офис открыт по будням и в субботу; воскресенье — выходной.</p><div class=\"local-offices\"><article class=\"local-office\" id=\"bataysk\"><a href=\"https://yandex.ru/maps/?text=%D0%91%D0%B0%D1%82%D0%B0%D0%B9%D1%81%D0%BA%2C%20%D1%83%D0%BB.%20%D0%9C.%20%D0%93%D0%BE%D1%80%D1%8C%D0%BA%D0%BE%D0%B3%D0%BE%2C%20152%20%2F%20%D1%83%D0%BB.%20%D0%9A%D1%83%D0%B9%D0%B1%D1%8B%D1%88%D0%B5%D0%B2%D0%B0%2C%20143\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"../../contacts/assets/bataysk.webp\" width=\"1260\" height=\"810\" loading=\"lazy\" decoding=\"async\" alt=\"Карта: Батайск, ул. М. Горького, 152 / ул. Куйбышева, 143\"></a><div><h3>ул. М. Горького, 152 / ул. Куйбышева, 143</h3><p>Батайск · Ростовская область</p><p>Пн–Пт: 09:00–18:00<br>Сб: 09:00–14:00<br>Вс: выходной</p><div class=\"local-actions\"><a class=\"local-button\" href=\"tel:+79885636444\">8 (988) 563-64-44</a><a class=\"local-text-link\" href=\"https://yandex.ru/maps/?text=%D0%91%D0%B0%D1%82%D0%B0%D0%B9%D1%81%D0%BA%2C%20%D1%83%D0%BB.%20%D0%9C.%20%D0%93%D0%BE%D1%80%D1%8C%D0%BA%D0%BE%D0%B3%D0%BE%2C%20152%20%2F%20%D1%83%D0%BB.%20%D0%9A%D1%83%D0%B9%D0%B1%D1%8B%D1%88%D0%B5%D0%B2%D0%B0%2C%20143\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть карту ↗</a></div></div></article></div></section>\n    <section class=\"local-section\"><h2>От выбора окна — <em class=\"heading-accent\">к установке</em></h2><div class=\"local-grid\"><div><h3>Что можно заказать</h3><p>Пластиковые окна ПВХ из профилей REHAU и PRO WINS, балконные блоки и остекление по индивидуальным размерам. Комплектацию подбираем под помещение, шум с улицы и нужное открывание.</p><a href=\"../../catalog/okna/\">Посмотреть оконные системы ↗</a></div><div><h3>Как получить цену с установкой</h3><p>Пришлите фото и примерные размеры, укажите адрес объекта. После замера согласуем изделие, монтаж и дополнительные работы. Уточните, нужны ли демонтаж, подоконник, отлив, сетка и откосы.</p><a href=\"../../ustanovka-okon/\">Как проходит установка ↗</a></div></div></section>\n    <section class=\"local-section\"><h2>Сколько стоят <em class=\"heading-accent\">пластиковые окна?</em></h2><p class=\"local-lead\">В каталоге указан ориентир на изделие — от 6 500 ₽ / м² без монтажа и доставки. Это не цена окна с установкой: итог зависит от размеров, профиля, стеклопакета, числа створок и состава работ.</p><a class=\"local-button\" href=\"../../calculator/\">Рассчитать своё окно</a></section>\n    <nav class=\"local-related\" aria-label=\"Выбор и заказ окон\"><a href=\"../../catalog/okna/\">Окна ПВХ и оконные системы ↗</a><a href=\"../../ustanovka-okon/\">Установка окон ↗</a><a href=\"../../calculator/\">Калькулятор стоимости ↗</a><a href=\"../../solutions/\">Примеры работ ↗</a></nav>\n  </main>","branch_ids":["bataysk"]}', 'Пластиковые окна в Батайске — купить с установкой | Спектр', 'Окна ПВХ «Спектр» в Батайске: ул. М. Горького, 152 / ул. Куйбышева, 143, телефоны и часы работы. Подбор оконных систем, замер и расчёт стоимости с установкой.', 'https://spektr-okna.ru/contacts/bataysk/')
ON DUPLICATE KEY UPDATE id = id;

