INSERT INTO `page_contacts` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/contacts/', 'Наши офисы Выберите ближайший', '{"main_html":"<main>\n        <section class=\"hero contacts-hero hero-cinema\" aria-labelledby=\"contactsTitle\">\n            <div class=\"contacts-hero-media\" aria-hidden=\"true\">\n                <img src=\"../assets/contacts-window-rain-poster.webp\" alt=\"\" width=\"1600\" height=\"900\" fetchpriority=\"high\" decoding=\"async\">\n                <video muted loop playsinline preload=\"none\" data-src=\"../assets/contacts-window-rain.mp4\" tabindex=\"-1\"></video>\n            </div>\n    <nav class=\"breadcrumbs wrap\" aria-label=\"Хлебные крошки\"><a href=\"../\">Главная</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Филиалы</span></nav>\n            <div class=\"wrap hero-grid\">\n                <div class=\"hero-copy section-copy\">\n                    <h1 id=\"contactsTitle\">Наши офисы<br><em class=\"heading-accent\">Выберите ближайший</em></h1>\n                    <p>Посетите ближайший салон «Спектр»: покажем образцы, поможем выбрать профиль и рассчитаем\n                        стоимость конструкции.</p>\n                </div>\n\n                <aside class=\"contacts-hero-help\" aria-labelledby=\"contactsHelpTitle\">\n                    <h2 id=\"contactsHelpTitle\">Поможем выбрать <em class=\"heading-accent\">удобный офис</em></h2>\n                    <p>Позвоните по единому номеру — подскажем ближайший филиал и запишем на бесплатный замер.</p>\n                    <a class=\"page-end-action\" href=\"tel:+79895175699\" aria-label=\"Позвонить в Спектр: 8 (989) 517-56-99\"><svg class=\"page-end-action-icon\" viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"m7 3 3 5-2.5 2.5a15 15 0 0 0 6 6L16 14l5 3c0 3-2 4-4 4C10 20 4 14 3 7c0-2 1-4 4-4Z\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg><span class=\"page-end-action-copy\"><span>Позвонить в «Спектр»</span><strong>8 (989) 517-56-99</strong></span><span class=\"page-end-action-arrow\" aria-hidden=\"true\">↗</span></a>\n                </aside>\n            </div>\n            <div class=\"wrap contacts-hero-bottom\">\n                <div class=\"hero-facts\" aria-label=\"Краткая информация\">\n                    <div><strong>6</strong><span>офисов продаж</span></div>\n                    <div><strong>2</strong><span>региона присутствия</span></div>\n                    <div><strong>1</strong><span>единый стандарт качества</span></div>\n                </div>\n                <button class=\"hero-video-toggle\" type=\"button\" hidden aria-label=\"Приостановить видео\"><span aria-hidden=\"true\">Ⅱ</span></button>\n            </div>\n        </section>\n\n        <section class=\"offices\" id=\"offices\" aria-labelledby=\"officesTitle\">\n            <div class=\"wrap\">\n                <div class=\"section-heading\">\n                    <div>\n\n                        <h2 id=\"officesTitle\">Наши <em class=\"heading-accent\">филиалы</em></h2>\n                    </div>\n\n                    <p class=\"section-intro\">Выберите регион и посмотрите адрес, телефон и режим работы ближайшего офиса.</p>\n                </div>\n\n                <div class=\"region-filters\" role=\"group\" aria-label=\"Фильтр по региону\">\n                    <button class=\"filter-button is-active\" type=\"button\" data-filter=\"all\">Все офисы</button>\n                    <button class=\"filter-button\" type=\"button\" data-filter=\"rostov\">Ростов-на-Дону</button>\n                    <button class=\"filter-button\" type=\"button\" data-filter=\"region\">Ростовская область</button>\n                    <button class=\"filter-button\" type=\"button\" data-filter=\"krasnodar\">Краснодарский край</button>\n                </div>\n\n                <p class=\"results-status\" id=\"resultsStatus\" role=\"status\"></p>\n\n                <div class=\"office-grid\" id=\"officeGrid\">\n                    <article class=\"office-card\" data-region=\"rostov\"\n                        data-search=\"ростов-на-дону александровка 40 лет победы 89\">\n                        <a class=\"office-map\"\n                            href=\"https://yandex.ru/maps/?text=Ростов-на-Дону%2C%20проспект%2040-летия%20Победы%2C%2089\"\n                            target=\"_blank\" rel=\"noopener\" aria-label=\"Открыть офис на карте\">\n                            <img src=\"assets/rostov-aleksandrovka.webp\" srcset=\"assets/rostov-aleksandrovka-small.webp 640w, assets/rostov-aleksandrovka.webp 1247w\" sizes=\"(max-width: 760px) calc(100vw - 34px), (max-width: 1000px) calc(100vw - 72px), 610px\" alt=\"Карта офиса Спектр: Ростов-на-Дону, проспект 40-летия Победы, 89\"\n                                loading=\"lazy\" width=\"1247\" height=\"796\" decoding=\"async\">\n                            <span>Открыть карту ↗</span>\n                        </a>\n                        <div class=\"office-body\">\n                            <header>\n                                <div><small>Ростовская область</small>\n                                    <h3><a href=\"rostov-na-donu/\">Ростов-на-Дону</a></h3>\n                                </div><span class=\"work-status\"\n                                    data-schedule=\"weekday:09:00-18:00;sat:09:00-14:00\"></span>\n                            </header>\n                            <dl>\n                                <div>\n                                    <dt>Адрес</dt>\n                                    <dd>проспект 40-летия Победы, 89</dd>\n                                </div>\n                                <div>\n                                    <dt>Телефон</dt>\n                                    <dd><a href=\"tel:+79882530344\">8 (988) 253-03-44</a></dd>\n                                </div>\n                                <div>\n                                    <dt>Почта</dt>\n                                    <dd><a href=\"mailto:40letpobedy.spektr@mail.ru\">40letpobedy.spektr@mail.ru</a></dd>\n                                </div>\n                                <div>\n                                    <dt>Режим работы</dt>\n                                    <dd>Пн–Пт: 09:00–18:00<br>Сб: 09:00–14:00<br>Вс: выходной</dd>\n                                </div>\n                            </dl>\n                            <a class=\"route-link\"\n                                href=\"https://yandex.ru/maps/?rtext=~Ростов-на-Дону%2C%20проспект%2040-летия%20Победы%2C%2089&rtt=auto\"\n                                target=\"_blank\" rel=\"noopener\">Построить маршрут <span>↗</span></a>\n                        </div>\n                    </article>\n\n                    <article class=\"office-card\" data-region=\"rostov\"\n                        data-search=\"ростов-на-дону западный зжм зорге 48\">\n                        <a class=\"office-map\"\n                            href=\"https://yandex.ru/maps/?text=Ростов-на-Дону%2C%20улица%20Зорге%2C%2048\"\n                            target=\"_blank\" rel=\"noopener\" aria-label=\"Открыть офис на карте\">\n                            <img src=\"assets/rostov-zorge.webp\" srcset=\"assets/rostov-zorge-small.webp 640w, assets/rostov-zorge.webp 1265w\" sizes=\"(max-width: 760px) calc(100vw - 34px), (max-width: 1000px) calc(100vw - 72px), 610px\" alt=\"Карта офиса Спектр на улице Зорге\" loading=\"lazy\" width=\"1265\" height=\"809\" decoding=\"async\">\n                            <span>Открыть карту ↗</span>\n                        </a>\n                        <div class=\"office-body\">\n                            <header>\n                                <div><small>Ростовская область</small>\n                                    <h3><a href=\"rostov-na-donu/\">Ростов-на-Дону</a></h3>\n                                </div><span class=\"work-status\"\n                                    data-schedule=\"weekday:09:00-18:00;sat:09:00-14:00\"></span>\n             