INSERT INTO `page_contacts` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/contacts/rostov-na-donu/', 'Пластиковые окна в Ростове-на-Дону', '{"main_html":"<main id=\"content\" class=\"wrap local-main\">\n    <nav class=\"breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../../\">Главная</a><span aria-hidden=\"true\">/</span><a href=\"../\">Филиалы</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Ростов-на-Дону</span></nav>\n    <header class=\"local-heading\"><h1>Пластиковые окна<br><em class=\"heading-accent\">в Ростове-на-Дону</em></h1><p>Два салона в Ростове-на-Дону: на проспекте 40-летия Победы и на улице Зорге. Выберите удобный офис, чтобы посмотреть образцы и обсудить замену окон.</p><div class=\"local-actions\"><a class=\"local-button\" href=\"../../#request\">Оставить заявку</a><a class=\"local-text-link\" href=\"#offices\">Адреса и телефоны ↗</a></div></header>\n    <section id=\"offices\" class=\"local-section\"><h2>Где купить <em class=\"heading-accent\">окна в Ростове-на-Дону?</em></h2><p class=\"local-lead\">На Александровке удобен офис на проспекте 40-летия Победы, 89. На Западном — на Зорге, 48. У второго офиса есть обеденный перерыв: проверьте часы работы перед поездкой.</p><div class=\"local-offices\"><article class=\"local-office\" id=\"rostov-aleksandrovka\"><a href=\"https://yandex.ru/maps/?text=%D0%A0%D0%BE%D1%81%D1%82%D0%BE%D0%B2-%D0%BD%D0%B0-%D0%94%D0%BE%D0%BD%D1%83%2C%20%D0%BF%D1%80%D0%BE%D1%81%D0%BF%D0%B5%D0%BA%D1%82%2040-%D0%BB%D0%B5%D1%82%D0%B8%D1%8F%20%D0%9F%D0%BE%D0%B1%D0%B5%D0%B4%D1%8B%2C%2089\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"../../contacts/assets/rostov-aleksandrovka.webp\" width=\"1260\" height=\"810\" loading=\"lazy\" decoding=\"async\" alt=\"Карта: Ростов-на-Дону, проспект 40-летия Победы, 89\"></a><div><h3>проспект 40-летия Победы, 89</h3><p>Ростов-на-Дону · Ростовская область</p><p>Пн–Пт: 09:00–18:00<br>Сб: 09:00–14:00<br>Вс: выходной</p><div class=\"local-actions\"><a class=\"local-button\" href=\"tel:+79882530344\">8 (988) 253-03-44</a><a class=\"local-text-link\" href=\"https://yandex.ru/maps/?text=%D0%A0%D0%BE%D1%81%D1%82%D0%BE%D0%B2-%D0%BD%D0%B0-%D0%94%D0%BE%D0%BD%D1%83%2C%20%D0%BF%D1%80%D0%BE%D1%81%D0%BF%D0%B5%D0%BA%D1%82%2040-%D0%BB%D0%B5%D1%82%D0%B8%D1%8F%20%D0%9F%D0%BE%D0%B1%D0%B5%D0%B4%D1%8B%2C%2089\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть карту ↗</a></div></div></article><article class=\"local-office\" id=\"rostov-zorge\"><a href=\"https://yandex.ru/maps/?text=%D0%A0%D0%BE%D1%81%D1%82%D0%BE%D0%B2-%D0%BD%D0%B0-%D0%94%D0%BE%D0%BD%D1%83%2C%20%D1%83%D0%BB.%20%D0%97%D0%BE%D1%80%D0%B3%D0%B5%2C%2048\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"../../contacts/assets/rostov-zorge.webp\" width=\"1260\" height=\"810\" loading=\"lazy\" decoding=\"async\" alt=\"Карта: Ростов-на-Дону, ул. Зорге, 48\"></a><div><h3>ул. Зорге, 48</h3><p>Ростов-на-Дону · Ростовская область</p><p>Пн–Пт: 09:00–18:00, перерыв 13:00–14:00<br>Сб: 09:00–14:00<br>Вс: выходной</p><div class=\"local-actions\"><a class=\"local-button\" href=\"tel:+79896164445\">8 (989) 616-44-45</a><a class=\"local-text-link\" href=\"https://yandex.ru/maps/?text=%D0%A0%D0%BE%D1%81%D1%82%D0%BE%D0%B2-%D0%BD%D0%B0-%D0%94%D0%BE%D0%BD%D1%83%2C%20%D1%83%D0%BB.%20%D0%97%D0%BE%D1%80%D0%B3%D0%B5%2C%2048\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть карту ↗</a></div></div></article></div></section>\n    <section class=\"local-section\"><h2>От выбора окна — <em class=\"heading-accent\">к установке</em></h2><div class=\"local-grid\"><div><h3>Что можно заказать</h3><p>Пластиковые окна ПВХ из профилей REHAU и PRO WINS, балконные блоки и остекление по индивидуальным размерам. Комплектацию подбираем под помещение, шум с улицы и нужное открывание.</p><a href=\"../../catalog/okna/\">Посмотреть оконные системы ↗</a></div><div><h3>Как получить цену с установкой</h3><p>Пришлите фото и примерные размеры, укажите адрес объекта. После замера согласуем изделие, монтаж и дополнительные работы. Уточните, нужны ли демонтаж, подоконник, отлив, сетка и откосы.</p><a href=\"../../ustanovka-okon/\">Как проходит установка ↗</a></div></div></section>\n    <section class=\"local-section\"><h2>Сколько стоят <em class=\"heading-accent\">пластиковые окна?</em></h2><p class=\"local-lead\">В каталоге указан ориентир на изделие — от 6 500 ₽ / м² без монтажа и доставки. Это не цена окна с установкой: итог зависит от размеров, профиля, стеклопакета, числа створок и состава работ.</p><a class=\"local-button\" href=\"../../calculator/\">Рассчитать своё окно</a></section>\n    <nav class=\"local-related\" aria-label=\"Выбор и заказ окон\"><a href=\"../../catalog/okna/\">Окна ПВХ и оконные системы ↗</a><a href=\"../../ustanovka-okon/\">Установка окон ↗</a><a href=\"../../calculator/\">Калькулятор стоимости ↗</a><a href=\"../../solutions/\">Примеры работ ↗</a></nav>\n  </main>","branch_ids":["rostov-aleksandrovka","rostov-zorge"]}', 'Пластиковые окна в Ростове-на-Дону — купить с установкой | Спектр', 'Окна ПВХ «Спектр» в Ростове-на-Дону: два офиса, телефоны и часы работы. Подбор оконных систем, замер и расчёт стоимости с установкой.', 'https://spektr-okna.ru/contacts/rostov-na-donu/')
ON DUPLICATE KEY UPDATE id = id;

