INSERT INTO `page_reviews` (path, title, content, seo_title, seo_description, canonical_url)
VALUES ('/reviews/', 'Отзывы наших клиентов', '{"main_html":"<main>\n    <section class=\"reviews-hero\">\n      <div class=\"wrap\">\n    <nav class=\"breadcrumbs\" aria-label=\"Хлебные крошки\"><a href=\"../\">Главная</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Отзывы</span></nav>\n        <div class=\"reviews-hero-grid\">\n          <div class=\"section-copy\">\n\n            <h1>Отзывы<br><em class=\"heading-accent\">наших клиентов</em></h1>\n            <p class=\"reviews-lead\">Красивые окна, аккуратная установка и внимание к срокам — в словах тех, кто уже выбрал «Спектр».</p>\n            <a class=\"secondary-link\" href=\"#customer-reviews\">Читать отзывы ↓</a>\n          </div>\n          <aside class=\"selection-rating\" aria-labelledby=\"networkRatingTitle\">\n            <span class=\"eyebrow\" id=\"networkRatingTitle\">Оценки на Яндекс Картах</span>\n            <div class=\"selection-score\" aria-label=\"Средняя оценка 4,5 из 5\">4,5<span>из 5</span></div>\n            <div class=\"selection-stars\" aria-hidden=\"true\"><span>★</span><span>★</span><span>★</span><span>★</span><span class=\"selection-star-half\">★</span></div>\n            <p class=\"rating-caption\">Среднее по 6 офисам продаж</p>\n            <p class=\"rating-note\">Среднее арифметическое рейтингов филиалов, а не отдельный рейтинг сети на Яндексе.</p>\n            <details class=\"rating-details\">\n              <summary>Оценки филиалов <span aria-hidden=\"true\">+</span></summary>\n              <ul class=\"rating-branches\">\n                <li data-branch-rating=\"4.4\"><a href=\"https://yandex.com/maps/org/spektr/1112121444/\" target=\"_blank\" rel=\"noopener noreferrer\">Ростов-на-Дону · 40-летия Победы, 89 ↗</a><strong>4,4</strong></li>\n                <li data-branch-rating=\"4.2\"><a href=\"https://yandex.com/maps/org/spektr/89988552903/\" target=\"_blank\" rel=\"noopener noreferrer\">Ростов-на-Дону · Зорге, 48 ↗</a><strong>4,2</strong></li>\n                <li data-branch-rating=\"4.9\"><a href=\"https://yandex.com/maps/org/spektr/1016878662/\" target=\"_blank\" rel=\"noopener noreferrer\">Азов · Ленина, 66 ↗</a><strong>4,9</strong></li>\n                <li data-branch-rating=\"4.7\"><a href=\"https://yandex.com/maps/org/spektr/205814194476/\" target=\"_blank\" rel=\"noopener noreferrer\">Кулешовка · Матросова, 11 ↗</a><strong>4,7</strong></li>\n                <li data-branch-rating=\"4.6\"><a href=\"https://yandex.com/maps/org/spektr/1076106315/\" target=\"_blank\" rel=\"noopener noreferrer\">Батайск · Горького, 152/143 ↗</a><strong>4,6</strong></li>\n                <li data-branch-rating=\"4.2\"><a href=\"https://yandex.com/maps/org/spektr/1014167758/\" target=\"_blank\" rel=\"noopener noreferrer\">Ейск · Карла Либкнехта, 70 ↗</a><strong>4,2</strong></li>\n              </ul>\n              <p class=\"rating-formula\">(4,4 + 4,2 + 4,9 + 4,7 + 4,6 + 4,2) / 6 = 4,5</p>\n            </details>\n            <p class=\"rating-updated\">Проверено <time datetime=\"2026-10-21\">21 октября 2026</time>. Оценки могут меняться.</p>\n          </aside>\n        </div>\n      </div>\n    </section>\n    <section class=\"reviews\" id=\"customer-reviews\" aria-labelledby=\"reviewsTitle\">\n      <div class=\"wrap\">\n        <div class=\"page-reviews-heading\">\n          <div><h2 id=\"reviewsTitle\">Отзывы <em class=\"heading-accent\">клиентов</em></h2></div>\n          <a class=\"secondary-link\" href=\"https://yandex.ru/maps/org/spektr/1016878662/reviews/\" target=\"_blank\" rel=\"noopener noreferrer\">Все отзывы на Яндекс Картах ↗</a>\n        </div>\n        <div class=\"review-tools\" hidden>\n          <div class=\"review-filters\" role=\"group\" aria-label=\"Темы отзывов\">\n            <button type=\"button\" data-topic=\"all\" aria-pressed=\"true\">Все темы</button>\n            <button type=\"button\" data-topic=\"quality\" aria-pressed=\"false\">Качество</button>\n            <button type=\"button\" data-topic=\"installation\" aria-pressed=\"false\">Монтаж</button>\n            <button type=\"button\" data-topic=\"deadlines\" aria-pressed=\"false\">Сроки</button>\n            <button type=\"button\" data-topic=\"service\" aria-pressed=\"false\">Сервис</button>\n            <button type=\"button\" data-topic=\"price\" aria-pressed=\"false\">Цена</button>\n          </div>\n          <p id=\"reviewStatus\" role=\"status\" aria-live=\"polite\"></p>\n        </div>\n        <div class=\"reviews-grid\" id=\"reviewGrid\">\n<article class=\"review-card\" data-rating=\"5\" data-topics=\"service price quality\" data-branch=\"1016878662\">\n            <div class=\"review-top\"><div class=\"review-avatar\" aria-hidden=\"true\">ВБ</div><div><h3>Вера Б.</h3><span>Яндекс Карты · Азов, Ленина, 66</span></div><span class=\"review-quote\" aria-hidden=\"true\">“</span></div>\n            <div class=\"review-stars\" aria-label=\"Оценка 5 из 5\">★★★★★</div>\n            <p>Очень довольна данной компанией. Прекрасное обслуживание, отличное качество, большой выбор и приемлемые цены. Спасибо всему персоналу за их работу. И отдельное спасибо консультанту Алёне. Девушка вежливая, все подробно объяснила и помогла с выбором.</p>\n            <footer><span>29 сентября</span><a class=\"review-verified\" href=\"https://yandex.ru/maps/org/1016878662/reviews?reviews%5BpublicId%5D=5jw1dnhnw06baqtdp8pnq874mm&amp;utm_source=review\" target=\"_blank\" rel=\"noopener noreferrer\">Оригинал на Яндекс Картах ↗</a></footer>\n          </article>\n          <article class=\"review-card\" data-rating=\"5\" data-topics=\"service installation quality deadlines\" data-branch=\"1112121444\">\n            <div class=\"review-top\"><div class=\"review-avatar\" aria-hidden=\"true\">МК</div><div><h3>Марина К.</h3><span>Яндекс Карты · Ростов-на-Дону, 40-летия Победы, 89</span></div><span class=\"review-quote\" aria-hidden=\"true\">“</span></div>\n            <div class=\"review-stars\" aria-label=\"Оценка 5 из 5\">★★★★★</div>\n            <p>В этой компании заказала шторы блэкаут, и москитные сетки на окна. Приехал мастер , все измерил показал каталог, помог выбрать шторы, подсказал какие лучше, я хотела выбрать подороже, но он сказал что которые дешевле хуже не будут. Через неделю приехал этот же мастер, и все установил. И правда шторы шикарные, все очень понравилось, москитные сетки тоже мастер все сам установил. Я заказывала на 40 летиея победы 89,  менеджер Светлана  очень отзывчивая, после того как все установили, звонила спрашивала все ли нормально. Я очень довольна. Спасибо вам большое.</p>\n            <footer><time datetime=\"2026-09-08\">8 сентября 2026 г.</time><a class=\"review-verified\" href=\"https://yandex.ru/maps/org/1112121444/reviews?reviews%5BpublicId%5D=0ynhw7azrnp2wz1t7mwtx5y3xw&amp;utm_source=review\" target=\"_blank\" rel=\"noopener noreferrer\">Оригинал на Яндекс Картах ↗</a></footer>\n          </article>\n          <article class=\"review-card\" data-rating=\"5\" data-topics=\"service quality\" data-branch=\"1016878662\">\n            <div class=\"review-top\"><div class=\"review-avatar\" aria-hidden=\"true\">АО</div><div><h3>Анна Омельяненко</h3><span>Яндекс Карты · Азов, Ленина, 66</span></div><span class=\"review-quote\" aria-hidden=\"true\">“</span></div>\n            <div class=\"review-stars\" aria-label=\"Оценка 5 из 5\">★★★★★</div>\n            <p>Спасибо большое за прекрасное обслуживание<br>Менеджер Алёна замечательная)) все подсказала, очень подробно все разъяснила!!! Побольше бы таких сотрудников ,которые с душой относятся к каждому клиенту<br>Спасибо за поставленные окна ,качество великолепное</p>\n            <footer><span>6 сентября</span><a class=\"review-verified\" href=\"https://yandex.ru/maps/org/1016878662/reviews?reviews%5BpublicId%5D=yccw90eenvet6x137t447dvpkm&amp;utm_source=review\" target=\"_blank\" rel=\"noopener noreferrer\">Оригинал на Яндекс Картах ↗</a></footer>\n          </article>\n          <article class=\"review-card\" data-rating=\"5\" data-topics=\"service installation quality deadlines\" data-branch=\"89988552903\">\n            <div class=\"review-top\"><div class=\"review-avatar\" aria-hidden=\"true\">ТЛ</div><div><h3>Татьяна Литвинова</h3><span>Яндекс Карты · Ростов-на-Дону, Зорге, 48</span></div><span class=\"review-quote\" aria-hidden=\"true\">“</span></div>\n            <div class=\"review-stars\" aria-label=\"Оценка 5 из 5\">★★★★★</div>\n            <p>Добрый день! Хочу поделится приятными впечатлениями. Решила поменять балконную дверь и окно, время пришло)) Выбрала компанию Спектр, знакомая посоветовала, почитала в интернете, пластик Энвин, без свинца. Позвонила, менеджер все понятно рассказала, объяснила, записала на замер. Потом мне прямо вот все понравилось, быстро профессионально, замер Артем сделал, договор заключили, через две недели привезли и СРАЗУ установили! Окна красивые, ребята отлично все установили. Теперь закажу откосы, а потом жалюзи)  Благодарю, до новых встреч</p>\n            <footer><time datetime=\"2026-07-03\">3 июля 2026 г.</time><a class=\"review-verified\" href=\"https://yandex.ru/maps/org/89988552903/reviews?reviews%5BpublicId%5D=qg1td1t0e0x0dtg8rgfxk4dcn4&amp;utm_source=review\" target=\"_blank\" rel=\"noopener noreferrer\">Оригинал на Яндекс Картах ↗</a></footer>\n          </article>\n          <article class=\"review-card\" data-rating=\"5\" data-topics=\"installation quality deadlines\" data-branch=\"1016878662\">\n            <div class=\"review-top\"><div class=\"review-avatar\" aria-hidden=\"true\">НО</div><div><h3>Наталья Олейникова</h3><span>Яндекс Карты · Азов, Ленина, 66</span></div><span class=\"review-quote\" aria-hidden=\"true\">“</span></div>\n            <div class=\"review-stars\" aria-label=\"Оценка 5 из 5\">★★★★★</div>\n            <p>Заказывали в офисе входные двери, с выбором помогли,мастер приехал быстро,дверь доставил сам , лишних движений делать не пришлось. Качество двери и монтаж полностью устроили, спасибо большое.</p>